import { useRef, useState } from "react";
import { useServerFn } from "@tanstack/react-start";
import { signMediaUpload, enforceMediaSize } from "@/lib/experiences.functions";
import { supabase } from "@/integrations/supabase/client";
import { Upload, Loader2, Check, Cpu } from "lucide-react";
import { toast } from "sonner";
import { MAX_UPLOAD_BYTES, formatBytes, canUseMultithread } from "@/lib/video-compress";

interface Props {
  label: string;
  accept: string;
  currentPath?: string | null;
  onUploaded: (path: string) => void;
  prefix: string; // e.g. "markers" or "media"
}

type Phase =
  | { kind: "idle" }
  | { kind: "compressing"; percent: number; note: string }
  | { kind: "uploading"; percent: number };

export function MediaUploader({ label, accept, currentPath, onUploaded, prefix }: Props) {
  const inputRef = useRef<HTMLInputElement>(null);
  const signFn = useServerFn(signMediaUpload);
  const enforceFn = useServerFn(enforceMediaSize);
  const [phase, setPhase] = useState<Phase>({ kind: "idle" });
  const [savings, setSavings] = useState<string | null>(null);

  const busy = phase.kind !== "idle";

  async function handleFile(original: File) {
    setSavings(null);
    let file = original;

    try {
      /* ---------------- Stage 1 — compression (video only) -------------- */
      if (original.type.startsWith("video/")) {
        const mt = canUseMultithread();
        setPhase({
          kind: "compressing",
          percent: 0,
          note: mt ? "" : "single-threaded — this may take longer",
        });

        const { compressVideo } = await import("@/lib/video-compress");
        const result = await compressVideo(original, (p) => {
          setPhase({
            kind: "compressing",
            percent: p.stage === "compressing" ? p.percent : 0,
            note:
              p.stage === "loading"
                ? "loading encoder…"
                : p.stage === "probing"
                  ? "reading video…"
                  : p.multithreaded
                    ? ""
                    : "single-threaded — this may take longer",
          });
        });

        if (result.fellBack) {
          if (original.size > MAX_UPLOAD_BYTES) {
            throw new Error(
              `Couldn't compress this video (${result.reason ?? "unknown error"}) and the original is ${formatBytes(
                original.size,
              )} — over the 50 MB limit. Trim the clip or compress it externally, then try again.`,
            );
          }
          toast.warning(
            `Compression skipped (${result.reason ?? "unavailable"}) — uploading the original at ${formatBytes(original.size)}.`,
          );
        } else {
          file = result.file;
          setSavings(
            `${formatBytes(result.originalBytes)} → ${formatBytes(result.compressedBytes)}`,
          );
        }
      }

      if (file.size > MAX_UPLOAD_BYTES) {
        throw new Error(
          `${formatBytes(file.size)} exceeds the 50 MB upload limit. Trim the clip or compress it externally first.`,
        );
      }

      /* ---------------- Stage 2 — upload -------------------------------- */
      setPhase({ kind: "uploading", percent: 0 });
      const ext = file.name.split(".").pop() || "bin";
      const path = `${prefix}/${crypto.randomUUID()}.${ext}`;
      const signed = await signFn({ data: { path, upsert: true, size: file.size } });

      const { error } = await supabase.storage
        .from("ar-media")
        .uploadToSignedUrl(signed.path, signed.token, file, {
          contentType: file.type,
          upsert: true,
        });
      if (error) throw error;

      setPhase({ kind: "uploading", percent: 100 });
      // Server-side backstop: verifies the real object size and deletes it
      // if a client bypassed the limit.
      await enforceFn({ data: { path: signed.path } });

      onUploaded(signed.path);
      toast.success(savings ? `${label} uploaded — compressed ${savings}` : `${label} uploaded`);
    } catch (e: any) {
      toast.error(e.message ?? "Upload failed");
    } finally {
      setPhase({ kind: "idle" });
    }
  }

  return (
    <div>
      <span className="text-xs text-muted-foreground">{label}</span>
      <div className="mt-1 flex items-center gap-2">
        <button
          type="button"
          onClick={() => inputRef.current?.click()}
          disabled={busy}
          className="flex-1 inline-flex items-center gap-2 rounded-md border border-dashed border-border bg-background px-3 py-2 text-xs hover:bg-accent disabled:opacity-50"
        >
          {phase.kind === "compressing" ? (
            <>
              <Cpu className="h-3 w-3 animate-pulse" /> Compressing {phase.percent}%
            </>
          ) : phase.kind === "uploading" ? (
            <>
              <Loader2 className="h-3 w-3 animate-spin" /> Uploading {phase.percent}%
            </>
          ) : currentPath ? (
            <>
              <Check className="h-3 w-3 text-primary" />
              <span className="truncate">{currentPath.split("/").pop()}</span>
              <span className="ml-auto text-muted-foreground">Replace</span>
            </>
          ) : (
            <>
              <Upload className="h-3 w-3" /> Choose file
            </>
          )}
        </button>
        <input
          ref={inputRef}
          type="file"
          accept={accept}
          className="hidden"
          onChange={(e) => {
            const f = e.target.files?.[0];
            if (f) handleFile(f);
            e.target.value = "";
          }}
        />
      </div>

      {phase.kind !== "idle" && (
        <div className="mt-2">
          <div className="h-1 w-full overflow-hidden rounded-full bg-muted">
            <div
              className={`h-full transition-[width] duration-200 ${
                phase.kind === "compressing" ? "bg-amber-500" : "bg-primary"
              }`}
              style={{ width: `${phase.percent}%` }}
            />
          </div>
          <p className="mt-1 text-[11px] text-muted-foreground">
            {phase.kind === "compressing"
              ? `Compressing on this device${phase.note ? ` — ${phase.note}` : ""}`
              : "Uploading to secure storage"}
          </p>
        </div>
      )}

      {phase.kind === "idle" && savings && (
        <p className="mt-1 text-[11px] text-primary">Compressed {savings}</p>
      )}
    </div>
  );
}

import { useEffect, useRef, useState } from "react";
import QRCode from "qrcode";
import { useServerFn } from "@tanstack/react-start";
import { Download, X, Printer, Lock, Globe, RefreshCw, Loader2 } from "lucide-react";
import { toast } from "sonner";
import { getShareCredentials, setAccessMode, regeneratePin } from "@/lib/access.functions";

interface Props {
  slug: string;
  title: string;
  /** "album" encodes one QR for the whole album (multi-target scanning). */
  kind?: "experience" | "album";
  /** Row id — enables the restricted-access controls (PIN, token, rotation). */
  id?: string;
  /** Called when the slug changes (switching to restricted mints a new one). */
  onSlugChange?: (slug: string) => void;
  onClose: () => void;
}

interface Share {
  slug: string;
  restricted: boolean;
  pin: string | null;
  tok: string | null;
  pinExpiresAt?: string | null;
}

export function QRCodeDialog({
  slug,
  title,
  kind = "experience",
  id,
  onSlugChange,
  onClose,
}: Props) {
  const [dataUrl, setDataUrl] = useState<string | null>(null);
  const [share, setShare] = useState<Share>({
    slug,
    restricted: false,
    pin: null,
    tok: null,
    pinExpiresAt: null,
  });
  const [loading, setLoading] = useState(Boolean(id));
  const [working, setWorking] = useState(false);

  const loadShare = useServerFn(getShareCredentials);
  const setMode = useServerFn(setAccessMode);
  const rotate = useServerFn(regeneratePin);
  const canvasRef = useRef<HTMLCanvasElement | null>(null);

  const path = kind === "album" ? `/ar/album/${share.slug}` : `/ar/${share.slug}`;
  // Always percent-encode: the token alphabet is base64url today, but never
  // assume a character subset stays URL-safe unencoded.
  const url = `${getPublicOrigin()}${path}${
    share.tok ? `?tok=${encodeURIComponent(share.tok)}` : ""
  }`;

  // PINs are stored hashed and QR tokens hashed — neither can be read back.
  // This only loads the access mode; issuing/rotating returns them once.
  useEffect(() => {
    if (!id) return;
    let alive = true;
    loadShare({ data: { kind, id } })
      .then((r: any) => {
        if (!alive) return;
        setShare({
          slug: r.slug,
          restricted: r.restricted,
          pin: r.pin,
          tok: r.tok,
          pinExpiresAt: r.pinExpiresAt ?? null,
        });
      })
      .catch((e: any) => toast.error(e?.message ?? "Couldn't load share settings"))
      .finally(() => alive && setLoading(false));
    return () => {
      alive = false;
    };
  }, [id, kind]);

  // Render the QR, overlaying the plaintext PIN on a light plate in the middle.
  useEffect(() => {
    let alive = true;
    (async () => {
      const canvas = document.createElement("canvas");
      await QRCode.toCanvas(canvas, url, {
        width: 720,
        margin: 2,
        errorCorrectionLevel: "H",
      });
      if (share.pin) {
        const ctx = canvas.getContext("2d");
        if (ctx) {
          const w = canvas.width;
          const plate = w * 0.26;
          const x = (w - plate) / 2;
          const y = (w - plate * 0.56) / 2;
          ctx.fillStyle = "#ffffff";
          ctx.fillRect(x, y, plate, plate * 0.56);
          ctx.strokeStyle = "#111111";
          ctx.lineWidth = Math.max(2, w * 0.004);
          ctx.strokeRect(x, y, plate, plate * 0.56);
          ctx.fillStyle = "#111111";
          ctx.textAlign = "center";
          ctx.textBaseline = "middle";
          ctx.font = `bold ${Math.round(plate * 0.34)}px monospace`;
          ctx.fillText(share.pin, w / 2, y + plate * 0.3);
        }
      }
      if (alive) {
        canvasRef.current = canvas;
        setDataUrl(canvas.toDataURL("image/png"));
      }
    })();
    return () => {
      alive = false;
    };
  }, [url, share.pin]);

  function download() {
    if (!dataUrl) return;
    const a = document.createElement("a");
    a.href = dataUrl;
    a.download = `${share.slug}-qr.png`;
    a.click();
  }

  function print() {
    const w = window.open("", "_blank", "width=800,height=1000");
    if (!w) return;
    w.document.write(`
      <html><head><title>${title} — AR marker</title>
      <style>
        body{font-family:sans-serif;text-align:center;padding:40px;}
        h1{font-family:serif;font-style:italic;font-size:32px;margin:0 0 8px;}
        p{color:#666;font-size:14px;margin:4px 0;}
        img{width:400px;height:400px;margin:24px 0;}
        code{background:#f4f4f4;padding:4px 8px;border-radius:4px;font-size:12px;}
        .pin{font-family:monospace;font-size:22px;letter-spacing:4px;color:#111;}
      </style></head>
      <body>
        <h1>${title}</h1>
        <p>${kind === "album" ? "Scan once, then point your camera at any photo in this album" : "Scan to view in AR"}</p>
        <img src="${dataUrl}" alt="QR code"/>
        ${share.pin ? `<p class="pin">PIN ${share.pin}</p><p>Type this PIN if the link is opened without scanning the card.</p>` : ""}
        <p><code>${url}</code></p>
      </body></html>`);
    w.document.close();
    setTimeout(() => w.print(), 300);
  }

  async function switchMode(mode: "public" | "restricted") {
    if (!id) return;
    setWorking(true);
    try {
      const r: any = await setMode({ data: { kind, id, mode } });
      setShare({
        slug: r.slug,
        restricted: r.restricted,
        pin: r.pin,
        tok: r.tok,
        pinExpiresAt: r.pinExpiresAt ?? null,
      });
      onSlugChange?.(r.slug);
      toast.success(
        mode === "restricted"
          ? "Now restricted — a new private link and PIN were issued."
          : "Now public — the PIN was removed.",
      );
    } catch (e: any) {
      toast.error(e?.message ?? "Couldn't change access mode");
    } finally {
      setWorking(false);
    }
  }

  async function rotatePin() {
    if (!id) return;
    if (
      !confirm(
        "Re-issue the PIN and QR token? Every previously printed card stops working immediately.",
      )
    )
      return;
    setWorking(true);
    try {
      const r: any = await rotate({ data: { kind, id } });
      setShare({
        slug: r.slug,
        restricted: true,
        pin: r.pin,
        tok: r.tok,
        pinExpiresAt: r.pinExpiresAt ?? null,
      });
      toast.success("New PIN issued — reprint the QR.");
    } catch (e: any) {
      toast.error(e?.message ?? "Couldn't regenerate PIN");
    } finally {
      setWorking(false);
    }
  }

  return (
    <div className="fixed inset-0 z-50 bg-black/60 backdrop-blur-sm flex items-center justify-center p-4">
      <div className="w-full max-w-md max-h-[90vh] overflow-y-auto rounded-2xl border border-border/60 bg-card p-6">
        <div className="flex items-center justify-between mb-4">
          <h2 className="text-xl font-serif italic">Share &amp; QR code</h2>
          <button onClick={onClose} className="p-1 rounded-md hover:bg-accent">
            <X className="h-4 w-4" />
          </button>
        </div>

        <div className="grid place-items-center py-2">
          {dataUrl ? (
            <img src={dataUrl} alt="QR" className="w-60 h-60 bg-white rounded-md" />
          ) : (
            <div className="w-60 h-60 bg-muted rounded-md animate-pulse" />
          )}
        </div>

        {id && (
          <div className="mt-3 rounded-xl border border-border/60 bg-background/40 p-3">
            {loading ? (
              <div className="flex items-center gap-2 text-xs text-muted-foreground">
                <Loader2 className="h-3 w-3 animate-spin" /> Loading access settings…
              </div>
            ) : (
              <>
                <div className="flex gap-2">
                  <button
                    disabled={working}
                    onClick={() => switchMode("public")}
                    className={`flex-1 inline-flex items-center justify-center gap-1.5 rounded-md border px-3 py-1.5 text-xs disabled:opacity-50 ${
                      share.restricted
                        ? "border-border text-muted-foreground hover:bg-accent"
                        : "border-primary/40 bg-primary/10 text-primary"
                    }`}
                  >
                    <Globe className="h-3.5 w-3.5" /> Public link
                  </button>
                  <button
                    disabled={working}
                    onClick={() => switchMode("restricted")}
                    className={`flex-1 inline-flex items-center justify-center gap-1.5 rounded-md border px-3 py-1.5 text-xs disabled:opacity-50 ${
                      share.restricted
                        ? "border-primary/40 bg-primary/10 text-primary"
                        : "border-border text-muted-foreground hover:bg-accent"
                    }`}
                  >
                    <Lock className="h-3.5 w-3.5" /> PIN protected
                  </button>
                </div>

                {share.restricted && (
                  <div className="mt-3 flex items-center gap-3">
                    <div>
                      <p className="text-[11px] text-muted-foreground">Access PIN</p>
                      <p className="font-mono text-lg tracking-[0.3em]">
                        {share.pin ?? "— hidden —"}
                      </p>
                      {!share.pin && (
                        <p className="text-[11px] text-muted-foreground">
                          Stored hashed — re-issue to see and print it again.
                        </p>
                      )}
                      {share.pinExpiresAt && (
                        <p className="text-[11px] text-muted-foreground">
                          Expires {new Date(share.pinExpiresAt).toLocaleDateString()}
                        </p>
                      )}
                    </div>
                    <button
                      disabled={working}
                      onClick={rotatePin}
                      className="ml-auto inline-flex items-center gap-1.5 rounded-md border border-border px-3 py-1.5 text-xs hover:bg-accent disabled:opacity-50"
                    >
                      <RefreshCw className={`h-3.5 w-3.5 ${working ? "animate-spin" : ""}`} />
                      Re-issue PIN + QR
                    </button>
                  </div>
                )}

                <p className="mt-2 text-[11px] leading-relaxed text-muted-foreground">
                  {share.restricted
                    ? "Scanning the printed QR opens instantly — the card itself is the credential. A forwarded link without the code asks for the PIN printed on the card."
                    : "Anyone with this link can open the experience. Switch to PIN protected to issue a private link and printable PIN."}
                </p>
              </>
            )}
          </div>
        )}

        {kind === "album" && (
          <p className="mt-3 text-xs text-center text-muted-foreground">
            One QR code covers the whole album — customers scan once, then point their camera at any
            photo to play its video.
          </p>
        )}
        <p className="mt-2 text-xs text-center text-muted-foreground break-all mb-4">{url}</p>

        <div className="flex gap-2">
          <button
            onClick={download}
            className="flex-1 inline-flex items-center justify-center gap-2 rounded-md border border-border px-4 py-2 text-sm hover:bg-accent"
          >
            <Download className="h-4 w-4" /> Download
          </button>
          <button
            onClick={print}
            className="flex-1 inline-flex items-center justify-center gap-2 rounded-md bg-primary px-4 py-2 text-sm text-primary-foreground hover:bg-primary/90"
          >
            <Printer className="h-4 w-4" /> Print
          </button>
        </div>
      </div>
    </div>
  );
}

function getPublicOrigin() {
  if (typeof window === "undefined") return "https://aetherphoto.shop";
  const { hostname, origin } = window.location;
  if (
    hostname === "localhost" ||
    hostname.includes("lovable.app") ||
    hostname.includes("lovableproject.com")
  ) {
    return "https://aetherphoto.shop";
  }
  return origin;
}

import { useEffect, useRef, useState } from "react";
import { Headset, X } from "lucide-react";
import {
  AR_STAGE_CLASS,
  applySceneHygiene,
  detectDeviceTier,
  ensureArStageStyles,
  releaseCameraStreams,
  rendererConfig,
} from "@/lib/ar-runtime";
import { ArVrToggle } from "@/components/ar/ModeToggle";

/**
 * Immersive VR viewer.
 *
 * Deliberately a *separate* scene from the AR stage: MindAR owns the camera
 * feed and drives its own render loop, and A-Frame only supports one active
 * WebXR session per scene. Mounting this component means the AR stage has
 * been unmounted (camera released, MindAR stopped, WebGL context disposed),
 * so there is never a second live context. Leaving VR unmounts this scene and
 * remounts the AR stage from scratch, which re-initialises tracking state
 * cleanly instead of trying to resume a half-torn-down session.
 */
export function VrStage({
  mediaUrl,
  mediaType,
  loop = true,
  onExit,
  ensureEngine,
}: {
  mediaUrl?: string | null;
  mediaType?: string | null;
  loop?: boolean;
  onExit: () => void;
  ensureEngine: () => Promise<void>;
}) {
  const rootRef = useRef<HTMLDivElement>(null);
  const sceneRef = useRef<any>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let disposed = false;
    ensureArStageStyles();
    const tier = detectDeviceTier();

    void (async () => {
      try {
        await ensureEngine();
        if (disposed || !rootRef.current) return;
        const root = rootRef.current;
        root.replaceChildren();

        const scene = document.createElement("a-scene");
        applySceneHygiene(scene);
        // VR needs the entry UI + keyboard shortcut back on this scene only.
        scene.setAttribute("vr-mode-ui", "enabled: true");
        scene.setAttribute("renderer", rendererConfig(tier));
        scene.setAttribute("background", "color: #050505");

        const assets = document.createElement("a-assets");
        if (mediaUrl && mediaType === "video") {
          const v = document.createElement("video");
          v.id = "vr-media";
          v.src = mediaUrl;
          v.loop = loop;
          v.muted = true;
          v.defaultMuted = true;
          v.playsInline = true;
          v.crossOrigin = "anonymous";
          v.preload = "auto";
          v.setAttribute("muted", "");
          v.setAttribute("playsinline", "");
          v.setAttribute("webkit-playsinline", "");
          assets.appendChild(v);
        } else if (mediaUrl && mediaType === "image") {
          const img = document.createElement("img");
          img.id = "vr-media";
          img.src = mediaUrl;
          img.crossOrigin = "anonymous";
          assets.appendChild(img);
        }
        scene.appendChild(assets);

        const cam = document.createElement("a-camera");
        cam.setAttribute("position", "0 1.6 0");
        cam.setAttribute("wasd-controls", "enabled: false");
        scene.appendChild(cam);

        // Floating cinema screen 2.6m in front of the viewer.
        if (mediaUrl) {
          const screen = document.createElement(mediaType === "image" ? "a-image" : "a-video");
          screen.setAttribute("src", "#vr-media");
          screen.setAttribute("width", "3.2");
          screen.setAttribute("height", mediaType === "image" ? "3.2" : "1.8");
          screen.setAttribute("position", "0 1.7 -2.6");
          scene.appendChild(screen);
        }

        const floor = document.createElement("a-circle");
        floor.setAttribute("rotation", "-90 0 0");
        floor.setAttribute("radius", "6");
        floor.setAttribute("color", "#0d0d10");
        floor.setAttribute("shader", "flat");
        scene.appendChild(floor);

        root.appendChild(scene);
        sceneRef.current = scene;

        scene.addEventListener("exit-vr", () => {
          if (!disposed) onExit();
        });
        scene.addEventListener(
          "renderstart",
          () => {
            const v = document.getElementById("vr-media");
            if (v instanceof HTMLVideoElement) void v.play().catch(() => {});
          },
          { once: true },
        );
      } catch (e: any) {
        if (!disposed) setError(e?.message ?? "VR mode failed to start");
      }
    })();

    return () => {
      disposed = true;
      try {
        sceneRef.current?.exitVR?.();
        sceneRef.current?.renderer?.dispose?.();
      } catch {
        /* already gone */
      }
      if (rootRef.current) {
        releaseCameraStreams(rootRef.current);
        rootRef.current.replaceChildren();
      }
      sceneRef.current = null;
    };
  }, [mediaUrl, mediaType, loop, onExit, ensureEngine]);

  return (
    <>
      <div ref={rootRef} className={AR_STAGE_CLASS} />
      <div className="fixed top-4 right-4 z-50 flex items-center gap-2">
        <ArVrToggle mode="vr" onChange={(m) => m === "ar" && onExit()} />
        <button
          onClick={onExit}
          aria-label="Exit VR"
          className="inline-flex items-center rounded-full bg-black/45 backdrop-blur p-1.5 text-white ring-1 ring-white/15 hover:bg-black/60"
        >
          <X className="h-3.5 w-3.5" />
        </button>
      </div>
      {error && (
        <div className="fixed inset-0 z-50 grid place-items-center bg-black/80 p-6 text-center text-white">
          <div>
            <Headset className="mx-auto mb-3 h-6 w-6 opacity-60" />
            <p className="text-sm text-white/70">{error}</p>
            <button
              onClick={onExit}
              className="mt-4 rounded-full bg-white px-5 py-2 text-sm text-black"
            >
              Back to AR
            </button>
          </div>
        </div>
      )}
    </>
  );
}

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";

const badgeVariants = cva(
  "inline-flex items-center rounded-md border px-2.5 py-0.5 text-xs font-semibold transition-colors focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2",
  {
    variants: {
      variant: {
        default: "border-transparent bg-primary text-primary-foreground shadow hover:bg-primary/80",
        secondary:
          "border-transparent bg-secondary text-secondary-foreground hover:bg-secondary/80",
        destructive:
          "border-transparent bg-destructive text-destructive-foreground shadow hover:bg-destructive/80",
        outline: "text-foreground",
      },
    },
    defaultVariants: {
      variant: "default",
    },
  },
);

export interface BadgeProps
  extends React.HTMLAttributes<HTMLDivElement>, VariantProps<typeof badgeVariants> {}

function Badge({ className, variant, ...props }: BadgeProps) {
  return <div className={cn(badgeVariants({ variant }), className)} {...props} />;
}

export { Badge, badgeVariants };

import * as React from "react";
import { Slot } from "@radix-ui/react-slot";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";

const buttonVariants = cva(
  "inline-flex items-center justify-center gap-2 whitespace-nowrap rounded-md text-sm font-medium cursor-pointer transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring disabled:pointer-events-none disabled:opacity-50 disabled:cursor-not-allowed [&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0",
  {
    variants: {
      variant: {
        default: "bg-primary text-primary-foreground shadow hover:bg-primary/90",
        destructive: "bg-destructive text-destructive-foreground shadow-sm hover:bg-destructive/90",
        outline:
          "border border-input bg-background shadow-sm hover:bg-accent hover:text-accent-foreground",
        secondary: "bg-secondary text-secondary-foreground shadow-sm hover:bg-secondary/80",
        ghost: "hover:bg-accent hover:text-accent-foreground",
        link: "text-primary underline-offset-4 hover:underline",
      },
      size: {
        default: "h-9 px-4 py-2",
        sm: "h-8 rounded-md px-3 text-xs",
        lg: "h-10 rounded-md px-8",
        icon: "h-9 w-9",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  },
);

export interface ButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>, VariantProps<typeof buttonVariants> {
  asChild?: boolean;
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant, size, asChild = false, ...props }, ref) => {
    const Comp = asChild ? Slot : "button";
    return (
      <Comp className={cn(buttonVariants({ variant, size, className }))} ref={ref} {...props} />
    );
  },
);
Button.displayName = "Button";

export { Button, buttonVariants };

import * as React from "react";
import * as LabelPrimitive from "@radix-ui/react-label";
import { Slot } from "@radix-ui/react-slot";
import {
  Controller,
  FormProvider,
  useFormContext,
  type ControllerProps,
  type FieldPath,
  type FieldValues,
} from "react-hook-form";

import { cn } from "@/lib/utils";
import { Label } from "@/components/ui/label";

const Form = FormProvider;

type FormFieldContextValue<
  TFieldValues extends FieldValues = FieldValues,
  TName extends FieldPath<TFieldValues> = FieldPath<TFieldValues>,
> = {
  name: TName;
};

const FormFieldContext = React.createContext<FormFieldContextValue | null>(null);

const FormField = <
  TFieldValues extends FieldValues = FieldValues,
  TName extends FieldPath<TFieldValues> = FieldPath<TFieldValues>,
>({
  ...props
}: ControllerProps<TFieldValues, TName>) => {
  return (
    <FormFieldContext.Provider value={{ name: props.name }}>
      <Controller {...props} />
    </FormFieldContext.Provider>
  );
};

const useFormField = () => {
  const fieldContext = React.useContext(FormFieldContext);
  const itemContext = React.useContext(FormItemContext);
  const { getFieldState, formState } = useFormContext();

  if (!fieldContext) {
    throw new Error("useFormField should be used within <FormField>");
  }

  if (!itemContext) {
    throw new Error("useFormField should be used within <FormItem>");
  }

  const fieldState = getFieldState(fieldContext.name, formState);

  const { id } = itemContext;

  return {
    id,
    name: fieldContext.name,
    formItemId: `${id}-form-item`,
    formDescriptionId: `${id}-form-item-description`,
    formMessageId: `${id}-form-item-message`,
    ...fieldState,
  };
};

type FormItemContextValue = {
  id: string;
};

const FormItemContext = React.createContext<FormItemContextValue | null>(null);

const FormItem = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(
  ({ className, ...props }, ref) => {
    const id = React.useId();

    return (
      <FormItemContext.Provider value={{ id }}>
        <div ref={ref} className={cn("space-y-2", className)} {...props} />
      </FormItemContext.Provider>
    );
  },
);
FormItem.displayName = "FormItem";

const FormLabel = React.forwardRef<
  React.ElementRef<typeof LabelPrimitive.Root>,
  React.ComponentPropsWithoutRef<typeof LabelPrimitive.Root>
>(({ className, ...props }, ref) => {
  const { error, formItemId } = useFormField();

  return (
    <Label
      ref={ref}
      className={cn(error && "text-destructive", className)}
      htmlFor={formItemId}
      {...props}
    />
  );
});
FormLabel.displayName = "FormLabel";

const FormControl = React.forwardRef<
  React.ElementRef<typeof Slot>,
  React.ComponentPropsWithoutRef<typeof Slot>
>(({ ...props }, ref) => {
  const { error, formItemId, formDescriptionId, formMessageId } = useFormField();

  return (
    <Slot
      ref={ref}
      id={formItemId}
      aria-describedby={!error ? `${formDescriptionId}` : `${formDescriptionId} ${formMessageId}`}
      aria-invalid={!!error}
      {...props}
    />
  );
});
FormControl.displayName = "FormControl";

const FormDescription = React.forwardRef<
  HTMLParagraphElement,
  React.HTMLAttributes<HTMLParagraphElement>
>(({ className, ...props }, ref) => {
  const { formDescriptionId } = useFormField();

  return (
    <p
      ref={ref}
      id={formDescriptionId}
      className={cn("text-[0.8rem] text-muted-foreground", className)}
      {...props}
    />
  );
});
FormDescription.displayName = "FormDescription";

const FormMessage = React.forwardRef<
  HTMLParagraphElement,
  React.HTMLAttributes<HTMLParagraphElement>
>(({ className, children, ...props }, ref) => {
  const { error, formMessageId } = useFormField();
  const body = error ? String(error?.message ?? "") : children;

  if (!body) {
    return null;
  }

  return (
    <p
      ref={ref}
      id={formMessageId}
      className={cn("text-[0.8rem] font-medium text-destructive", className)}
      {...props}
    >
      {body}
    </p>
  );
});
FormMessage.displayName = "FormMessage";

export {
  useFormField,
  Form,
  FormItem,
  FormLabel,
  FormControl,
  FormDescription,
  FormMessage,
  FormField,
};

