import { useEffect, useState } from "react";
import * as THREE from "three";

/**
 * Lightweight native Three.js texture hook.
 * Avoids pulling in the massive @react-three/drei package.
 */
export function useImageTexture(url: string): THREE.Texture {
  const [texture, setTexture] = useState<THREE.Texture>(() => {
    if (typeof window === "undefined") return new THREE.Texture();
    const loader = new THREE.TextureLoader();
    const tex = loader.load(url);
    tex.colorSpace = THREE.SRGBColorSpace;
    return tex;
  });

  useEffect(() => {
    if (typeof window === "undefined") return;
    const loader = new THREE.TextureLoader();
    loader.load(url, (tex) => {
      tex.colorSpace = THREE.SRGBColorSpace;
      setTexture(tex);
    });
  }, [url]);

  return texture;
}

export function useDirectVideoTexture(
  url: string,
  opts?: { muted?: boolean; loop?: boolean; playsInline?: boolean },
): THREE.VideoTexture {
  const [videoTexture, setVideoTexture] = useState<THREE.VideoTexture>(() => {
    if (typeof window === "undefined") {
      return new THREE.VideoTexture({} as HTMLVideoElement);
    }
    const video = document.createElement("video");
    video.src = url;
    video.crossOrigin = "anonymous";
    video.loop = opts?.loop ?? true;
    video.muted = opts?.muted ?? true;
    video.playsInline = opts?.playsInline ?? true;
    video.autoplay = true;
    video.play().catch(() => {});
    const vt = new THREE.VideoTexture(video);
    vt.colorSpace = THREE.SRGBColorSpace;
    return vt;
  });

  useEffect(() => {
    if (typeof window === "undefined") return;
    const video = document.createElement("video");
    video.src = url;
    video.crossOrigin = "anonymous";
    video.loop = opts?.loop ?? true;
    video.muted = opts?.muted ?? true;
    video.playsInline = opts?.playsInline ?? true;
    video.autoplay = true;
    video.play().catch(() => {});
    const vt = new THREE.VideoTexture(video);
    vt.colorSpace = THREE.SRGBColorSpace;
    setVideoTexture(vt);

    return () => {
      video.pause();
      video.removeAttribute("src");
      video.load();
      vt.dispose();
    };
  }, [url]);

  return videoTexture;
}

import { createServerFn } from "@tanstack/react-start";
import { z } from "zod";
import { setCookie } from "@tanstack/react-start/server";
import { requireSupabaseAuth } from "@/integrations/supabase/auth-middleware";

const Kind = z.enum(["album", "experience"]);

/** Default PIN lifetime. Rotate before this and reprint the card. */
const PIN_TTL_DAYS = 180;
/** QR access tokens outlive PINs — they are cheap to revoke individually. */
const TOKEN_TTL_DAYS = 365;

/* ------------------------------------------------------------------ */
/* Public: manual PIN entry                                            */
/* ------------------------------------------------------------------ */

/**
 * Checks a PIN against the bcrypt hash held in Postgres. Nothing reversible
 * is stored, so even we cannot read a PIN back after it is issued.
 *
 * Rate limited to 5 failures/hour/IP with a 15-minute lockout per slug, and
 * every failure is written to the audit log. The response never discloses
 * attempt counts or lockout timing — except for an expired PIN, where a
 * generic "incorrect" would send the customer down the wrong path.
 */
export const submitAccessPin = createServerFn({ method: "POST" })
  .validator((raw) =>
    z
      .object({
        kind: Kind,
        slug: z.string().min(1).max(120),
        pin: z.string().min(1).max(32),
      })
      .parse(raw),
  )
  .handler(async ({ data }) => {
    const { callerIp, auditPinFailure } = await import("@/lib/content-access.server");
    const { accessCookieName, signAccessCookie, ACCESS_COOKIE_MAX_AGE } =
      await import("@/lib/access.server");
    const { supabaseAdmin } = await import("@/integrations/supabase/client.server");

    const ip = callerIp();

    const { data: allowed } = await supabaseAdmin.rpc("pin_attempts_allowed", {
      _slug: data.slug,
      _ip: ip,
    });
    if (allowed === false) {
      return { ok: false as const, reason: "invalid" as const, message: "Incorrect PIN." };
    }

    const { data: result } = await supabaseAdmin.rpc("verify_content_pin", {
      _kind: data.kind,
      _slug: data.slug,
      _pin: data.pin,
    });

    if (result !== "ok") {
      await supabaseAdmin.rpc("pin_record_failure", { _slug: data.slug, _ip: ip });
      await auditPinFailure(data.kind, data.slug, ip);
      if (result === "pin_expired") {
        return {
          ok: false as const,
          reason: "pin_expired" as const,
          message: "This PIN has expired. Ask for a new card or a fresh link.",
        };
      }
      return { ok: false as const, reason: "invalid" as const, message: "Incorrect PIN." };
    }

    await supabaseAdmin.rpc("pin_clear_failures", { _slug: data.slug, _ip: ip });

    const expiresAt = Date.now() + ACCESS_COOKIE_MAX_AGE * 1000;
    setCookie(
      accessCookieName(data.kind, data.slug),
      await signAccessCookie(data.slug, expiresAt),
      {
        httpOnly: true,
        secure: true,
        sameSite: "lax",
        path: "/",
        maxAge: ACCESS_COOKIE_MAX_AGE,
      },
    );

    return { ok: true as const, reason: "ok" as const };
  });

/* ------------------------------------------------------------------ */
/* Admin/owner: issue + rotate credentials                             */
/* ------------------------------------------------------------------ */

async function loadOwnedRow(supabase: any, kind: "album" | "experience", id: string) {
  const table = kind === "album" ? "albums" : "ar_experiences";
  const { data, error } = await supabase
    .from(table)
    .select("id, slug, title, access_mode, pin_created_at, pin_expires_at")
    .eq("id", id)
    .maybeSingle();
  if (error) throw new Error(error.message);
  if (!data) throw new Response("Forbidden", { status: 403 });
  return data;
}

/** Mints a fresh PIN + QR access token for a row the caller owns. */
async function issueCredentials(kind: "album" | "experience", id: string) {
  const { supabaseAdmin } = await import("@/integrations/supabase/client.server");

  // PIN is generated in Postgres with gen_random_bytes + rejection sampling.
  const { data: pin, error: genErr } = await supabaseAdmin.rpc("generate_content_pin", {
    _length: 6,
  });
  if (genErr) throw new Error(genErr.message);

  const { data: pinExpires, error: setErr } = await supabaseAdmin.rpc("set_content_pin", {
    _kind: kind,
    _id: id,
    _pin: pin as string,
    _ttl_days: PIN_TTL_DAYS,
  });
  if (setErr) throw new Error(setErr.message);

  // Old printed QR codes stop working the moment credentials are re-issued.
  await supabaseAdmin.rpc("revoke_content_access_tokens", {
    _kind: kind,
    _content_id: id,
  });

  const { data: tok, error: tokErr } = await supabaseAdmin.rpc("issue_content_access_token", {
    _kind: kind,
    _content_id: id,
    _ttl_days: TOKEN_TTL_DAYS,
    _label: "printed-qr",
  });
  if (tokErr) throw new Error(tokErr.message);

  return { pin: pin as string, tok: tok as string, pinExpiresAt: pinExpires as string };
}

/**
 * Share state for the owner. The PIN is NOT returned here — it only exists in
 * plaintext at the moment it is issued. Reprinting requires re-issuing.
 */
export const getShareCredentials = createServerFn({ method: "POST" })
  .middleware([requireSupabaseAuth])
  .validator((raw) => z.object({ kind: Kind, id: z.string().uuid() }).parse(raw))
  .handler(async ({ data, context }) => {
    const row = await loadOwnedRow(context.supabase, data.kind, data.id);
    return {
      slug: row.slug as string,
      title: row.title as string,
      restricted: row.access_mode === "restricted",
      pin: null as string | null,
      tok: null as string | null,
      pinExpiresAt: (row.pin_expires_at ?? null) as string | null,
    };
  });

/**
 * Switches content between public and restricted.
 * Going restricted mints a fresh 12-16 char slug, a fresh PIN and a fresh QR
 * token, so the old public URL stops resolving. Going public wipes the PIN
 * and revokes every outstanding QR token.
 */
export const setAccessMode = createServerFn({ method: "POST" })
  .middleware([requireSupabaseAuth])
  .validator((raw) =>
    z
      .object({ kind: Kind, id: z.string().uuid(), mode: z.enum(["public", "restricted"]) })
      .parse(raw),
  )
  .handler(async ({ data, context }) => {
    const row = await loadOwnedRow(context.supabase, data.kind, data.id);
    const table = data.kind === "album" ? "albums" : "ar_experiences";
    const { supabaseAdmin } = await import("@/integrations/supabase/client.server");

    if (data.mode === "public") {
      const { error } = await context.supabase
        .from(table)
        .update({
          access_mode: "public",
          pin_hash: null,
          pin_created_at: null,
          pin_expires_at: null,
          pin_updated_at: null,
        })
        .eq("id", data.id);
      if (error) throw new Error(error.message);
      await supabaseAdmin.rpc("revoke_content_access_tokens", {
        _kind: data.kind,
        _content_id: data.id,
      });
      return {
        slug: row.slug as string,
        pin: null,
        tok: null,
        pinExpiresAt: null,
        restricted: false as const,
      };
    }

    const { generateRestrictedSlug } = await import("@/lib/access.server");
    const slug = generateRestrictedSlug();

    const { error } = await context.supabase
      .from(table)
      .update({ access_mode: "restricted", slug, show_in_gallery: false })
      .eq("id", data.id);
    if (error) throw new Error(error.message);

    const issued = await issueCredentials(data.kind, data.id);
    return { slug, ...issued, restricted: true as const };
  });

/**
 * Rotates the PIN and the QR token together — every previously printed card
 * stops working immediately. This is also the only way to see a PIN again,
 * because nothing reversible is stored.
 */
export const regeneratePin = createServerFn({ method: "POST" })
  .middleware([requireSupabaseAuth])
  .validator((raw) => z.object({ kind: Kind, id: z.string().uuid() }).parse(raw))
  .handler(async ({ data, context }) => {
    const row = await loadOwnedRow(context.supabase, data.kind, data.id);
    if (row.access_mode !== "restricted") throw new Error("Content is not restricted");

    const issued = await issueCredentials(data.kind, data.id);

    await context.supabase.from("audit_log").insert({
      actor_id: context.userId,
      action: "pin.regenerated",
      target_type: data.kind,
      target_id: row.slug,
    });

    return { slug: row.slug as string, ...issued, restricted: true as const };
  });

import { createServerFn } from "@tanstack/react-start";
import { requireSupabaseAuth } from "@/integrations/supabase/auth-middleware";

/**
 * Self-scoped account read (own profile + own licence, if the deployment has
 * a licences table at all).
 *
 * This lives outside the admin approvals module on purpose: that module
 * is admin/issuer-only and is stripped from customer (client-app) deliveries,
 * but the holding page at /pending still has to work there.
 */
export const getMyAccount = createServerFn({ method: "GET" })
  .middleware([requireSupabaseAuth])
  .handler(async ({ context }) => {
    const { data: profile, error } = await context.supabase
      .from("profiles")
      .select("id, display_name, email, approval_status, approval_decided_at, rejection_reason")
      .eq("id", context.userId)
      .maybeSingle();
    if (error) throw new Error(error.message);

    // Client-app builds have no licences table; a failure here is not fatal.
    let license: unknown = null;
    try {
      const { data } = await context.supabase
        .from("licenses")
        .select("license_key, plan, status, max_activations, issued_at, expires_at")
        .eq("owner_user_id", context.userId)
        .maybeSingle();
      license = data ?? null;
    } catch {
      license = null;
    }

    return { profile: profile ?? null, license: license as Record<string, any> | null };
  });

import type { SupabaseClient } from "@supabase/supabase-js";

/**
 * Server-side admin gate for server functions.
 *
 * The check runs with the CALLER's own Supabase client (RLS applies), so a
 * user can only ever see their own `user_roles` row — a forged request body
 * or a tampered client bundle cannot promote anybody. Never use the service
 * role client to establish that the caller is an admin.
 *
 * Throws a plain 403 Response so unauthorised callers get a safe, generic
 * error with no schema or role details leaked.
 */
export async function requireAdmin(context: {
  supabase: SupabaseClient<any, any, any>;
  userId: string;
}): Promise<void> {
  const { data, error } = await context.supabase
    .from("user_roles")
    .select("role")
    .eq("user_id", context.userId)
    .eq("role", "admin")
    .maybeSingle();

  if (error || !data) {
    throw new Response("Forbidden", { status: 403 });
  }
}

/** Non-throwing variant, for UI that only needs to branch on the role. */
export async function isAdmin(context: {
  supabase: SupabaseClient<any, any, any>;
  userId: string;
}): Promise<boolean> {
  const { data } = await context.supabase
    .from("user_roles")
    .select("role")
    .eq("user_id", context.userId)
    .eq("role", "admin")
    .maybeSingle();
  return !!data;
}

/**
 * Shared runtime helpers for the MindAR + A-Frame viewers.
 *
 * Everything in here is scoped to the AR stage container (`.ar-stage-root`).
 * No global page CSS is modified — the stylesheet below is injected once at
 * runtime and every selector is nested under the AR container class.
 *
 * Why this file exists (root causes it addresses):
 *
 * 1. FIT — MindAR's internal `_resize()` measures `container.clientWidth /
 *    clientHeight` (the <a-scene> box) and sizes the camera video + three.js
 *    camera from it. The viewers previously set `height: 100vh` on the scene.
 *    On mobile `100vh` is the *largest* possible viewport (URL bar collapsed),
 *    so while the bar is visible the scene box is taller than what the user
 *    can see: the camera feed is scaled for a taller box and the projection
 *    aspect no longer matches the visible area — content sits off-centre and
 *    overflows under the browser chrome.
 * 2. RESIZE — MindAR binds `window.resize` only. It never listens to
 *    `orientationchange`, `visualViewport` resize (URL-bar collapse, iOS
 *    keyboard/zoom) and never re-runs after the camera track flips its
 *    videoWidth/videoHeight on rotation. On iOS the single `resize` event
 *    fires *before* the video dimensions swap, so the fit is computed from
 *    stale dimensions and stays wrong until the next unrelated resize.
 * 3. LAG — MindAR takes whatever resolution getUserMedia hands it (often
 *    1280x720+ at 60fps). The tracker downsamples per frame on the CPU, so
 *    input resolution is the single biggest cost on low-end phones.
 */

export const AR_STAGE_CLASS = "ar-stage-root";

const STYLE_ID = "ar-stage-scoped-styles";

/**
 * Injects the AR-only stylesheet once. All rules are scoped under
 * `.ar-stage-root` so nothing outside the AR viewer is affected.
 */
export function ensureArStageStyles() {
  if (typeof document === "undefined") return;
  if (document.getElementById(STYLE_ID)) return;
  const style = document.createElement("style");
  style.id = STYLE_ID;
  style.textContent = `
.${AR_STAGE_CLASS} {
  position: fixed;
  inset: 0;
  width: 100vw;
  height: 100vh;            /* fallback for browsers without dvh */
  height: 100dvh;           /* tracks the *visible* viewport on mobile */
  overflow: hidden;
  touch-action: manipulation;
  background: #000;
}
.${AR_STAGE_CLASS} > a-scene,
.${AR_STAGE_CLASS} > a-scene .a-canvas {
  position: absolute !important;
  inset: 0 !important;
  width: 100% !important;
  height: 100% !important;
  display: block;
}
/* MindAR positions its camera feed with inline px values; keep it clipped
   to the stage instead of the document. */
.${AR_STAGE_CLASS} video {
  position: absolute;
  max-width: none;
}
/* Safe-area padding for the AR HUD only (notch / home indicator). */
.ar-stage-safe-top { padding-top: max(1rem, env(safe-area-inset-top)); }
.ar-stage-safe-bottom { padding-bottom: max(1rem, env(safe-area-inset-bottom)); }
`;
  document.head.appendChild(style);
}

/* ------------------------------------------------------------------ */
/* Device tiering                                                      */
/* ------------------------------------------------------------------ */

export type DeviceTier = "low" | "mid" | "high";

const PERF_KEY = "aether-ar-perf-mode";

/** User-forced performance mode. "lite" pins the low tier on old hardware. */
export type PerfMode = "auto" | "lite";

export function getPerfMode(): PerfMode {
  if (typeof localStorage === "undefined") return "auto";
  return localStorage.getItem(PERF_KEY) === "lite" ? "lite" : "auto";
}

export function setPerfMode(mode: PerfMode) {
  if (typeof localStorage === "undefined") return;
  if (mode === "lite") localStorage.setItem(PERF_KEY, "lite");
  else localStorage.removeItem(PERF_KEY);
}

/**
 * Cheap, synchronous capability probe. deviceMemory/hardwareConcurrency are
 * absent on iOS Safari, so we fall back to DPR × screen size heuristics.
 */
export function detectDeviceTier(): DeviceTier {
  if (typeof navigator === "undefined") return "mid";
  if (getPerfMode() === "lite") return "low";
  const nav = navigator as Navigator & {
    deviceMemory?: number;
    hardwareConcurrency?: number;
  };
  const mem = nav.deviceMemory ?? 0;
  const cores = nav.hardwareConcurrency ?? 0;
  const dpr = typeof window !== "undefined" ? window.devicePixelRatio || 1 : 1;

  if ((mem && mem <= 3) || (cores && cores <= 4)) return "low";
  if ((mem && mem >= 8) || (cores && cores >= 8)) return dpr > 3 ? "mid" : "high";
  return "mid";
}

/** Longest camera edge we let the tracker chew on, per tier. */
const CAMERA_CAP: Record<DeviceTier, number> = {
  low: 480,
  mid: 854,
  high: 1280,
};

/** Camera framerate cap — every extra frame is a full CPU tracking pass. */
const FPS_CAP: Record<DeviceTier, number> = {
  low: 24,
  mid: 30,
  high: 30,
};

/** Canvas cap keeps fragment cost bounded on high-DPR phones. */
const CANVAS_CAP: Record<DeviceTier, number> = {
  low: 720,
  mid: 1280,
  high: 1600,
};

/** Hard ceiling on devicePixelRatio — the single biggest fragment-cost lever. */
const DPR_CAP: Record<DeviceTier, number> = {
  low: 1,
  mid: 1.5,
  high: 2,
};

/**
 * MindAR image-tracking config string.
 *
 * The previous values (filterMinCF: 0.001 / filterBeta: 1000 /
 * warmupTolerance: 3 / missTolerance: 3) were MindAR's own defaults, i.e. no
 * tuning at all. The One-Euro filter behaves like this:
 *   filterMinCF  — cutoff at rest. LOWER = more smoothing when the phone is
 *                  still (kills the micro-jitter of a handheld shot).
 *   filterBeta   — how fast the cutoff opens up with motion. HIGHER = less
 *                  lag while panning, at the cost of jitter.
 * We therefore lower minCF (steadier lock) and keep beta high enough that a
 * pan still feels attached. Low-tier phones get slightly more smoothing
 * because their frame times are longer and noisier.
 *
 *   warmupTolerance — frames a target must be seen before it is declared
 *                     found. 2 = snappier lock-on than the default 5.
 *   missTolerance   — frames it may be missed before "lost". 4 keeps the
 *                     overlay alive through a blink/blur instead of flashing.
 *   maxTrack        — each simultaneously tracked target costs a full
 *                     tracking pass per frame. Always 1 unless the album
 *                     genuinely shows two prints at once.
 */
export function mindarConfig(opts: {
  imageTargetSrc: string;
  tier: DeviceTier;
  maxTrack?: number;
}) {
  const { imageTargetSrc, tier, maxTrack = 1 } = opts;
  const filterMinCF = tier === "low" ? 0.00008 : 0.0001;
  const filterBeta = tier === "low" ? 400 : 1000;
  return [
    `imageTargetSrc: ${imageTargetSrc}`,
    "autoStart: true",
    "uiScanning: no",
    "uiLoading: no",
    "uiError: no",
    `maxTrack: ${maxTrack}`,
    `filterMinCF: ${filterMinCF}`,
    `filterBeta: ${filterBeta}`,
    "warmupTolerance: 2",
    "missTolerance: 4",
  ].join("; ");
}

/**
 * A-Frame renderer config. `colorManagement` stays on (otherwise video looks
 * washed out); `physicallyCorrectLights` and `color-space` are removed —
 * both are no-ops in A-Frame 1.5 / three r1xx and only emit deprecation spam.
 */
export function rendererConfig(tier: DeviceTier) {
  const cap = CANVAS_CAP[tier];
  return [
    "colorManagement: true",
    `antialias: ${tier === "high"}`,
    "precision: mediump",
    "sortObjects: false",
    "logarithmicDepthBuffer: false",
    `maxCanvasWidth: ${cap}`,
    `maxCanvasHeight: ${cap}`,
  ].join(", ");
}

/**
 * Strips A-Frame's built-in extras we never use. Each of these otherwise
 * costs DOM, listeners, a default light rig (2 extra lights => extra shader
 * permutations and draw setup) or an extra rAF-driven overlay.
 */
export function applySceneHygiene(scene: HTMLElement) {
  scene.setAttribute("vr-mode-ui", "enabled: false");
  scene.setAttribute("device-orientation-permission-ui", "enabled: false");
  scene.setAttribute("keyboard-shortcuts", "enterVR: false; exitVR: false");
  // a-video / a-image use unlit materials — the default light rig is dead weight.
  scene.setAttribute("light", "defaultLightsEnabled: false");
  scene.setAttribute("shadow", "enabled: false");
  scene.setAttribute("embedded", "");
  // NOTE: no `stats` attribute at all. `stats="false"` still registers the
  // component and adds a per-frame rAF sampler on some A-Frame builds.
  scene.removeAttribute("stats");
}

/* ------------------------------------------------------------------ */
/* Viewport fit                                                        */
/* ------------------------------------------------------------------ */

type Cleanup = () => void;

/**
 * Keeps the A-Frame canvas, the three.js camera projection and MindAR's
 * camera-feed transform in sync with the *visible* viewport.
 *
 * Also caps the camera track resolution/framerate once the stream is live —
 * MindAR does not expose getUserMedia constraints, but the track can be
 * re-constrained after the fact, which is the single biggest tracking-lag
 * lever on low-end hardware.
 */
export function attachArViewportFit(scene: any, tier: DeviceTier = detectDeviceTier()): Cleanup {
  if (typeof window === "undefined") return () => {};
  let disposed = false;
  let frame = 0;

  const runFit = () => {
    if (disposed || !scene?.isConnected) return;
    try {
      // 1. A-Frame: renderer size + camera aspect from the container box.
      scene.resize?.();
      // 2. MindAR: camera-feed cover transform + projection fov/aspect.
      scene.systems?.["mindar-image-system"]?._resize?.();
    } catch {
      /* scene torn down mid-flight */
    }
  };

  const schedule = () => {
    if (disposed) return;
    cancelAnimationFrame(frame);
    frame = requestAnimationFrame(() => {
      runFit();
      // Second pass on the next tick: on iOS the video's intrinsic
      // dimensions swap one frame *after* the resize event fires.
      setTimeout(runFit, 250);
    });
  };

  window.addEventListener("resize", schedule);
  window.addEventListener("orientationchange", schedule);
  const vv = window.visualViewport;
  vv?.addEventListener("resize", schedule);
  vv?.addEventListener("scroll", schedule);
  const mq = window.matchMedia("(orientation: portrait)");
  mq.addEventListener?.("change", schedule);

  // Constrain the camera track + fit again once the feed actually starts.
  let polls = 0;
  let pollTimer: ReturnType<typeof setTimeout> | null = null;
  const tuneStream = () => {
    if (disposed) return;
    const video = scene.systems?.["mindar-image-system"]?.video as HTMLVideoElement | undefined;
    if (video?.videoWidth) {
      const stream = video.srcObject;
      if (stream instanceof MediaStream) {
        const track = stream.getVideoTracks()[0];
        void track
          ?.applyConstraints({
            width: { max: CAMERA_CAP[tier] },
            frameRate: { max: FPS_CAP[tier] },
          })
          .catch(() => {});
      }
      video.addEventListener("loadedmetadata", schedule);
      video.addEventListener("resize", schedule);
      schedule();
      return;
    }
    if (polls++ < 60) pollTimer = setTimeout(tuneStream, 250);
  };
  tuneStream();

  scene.addEventListener?.("renderstart", schedule);
  scene.addEventListener?.("arReady", schedule);
  schedule();

  return () => {
    disposed = true;
    cancelAnimationFrame(frame);
    if (pollTimer) clearTimeout(pollTimer);
    window.removeEventListener("resize", schedule);
    window.removeEventListener("orientationchange", schedule);
    vv?.removeEventListener("resize", schedule);
    vv?.removeEventListener("scroll", schedule);
    mq.removeEventListener?.("change", schedule);
    scene.removeEventListener?.("renderstart", schedule);
    scene.removeEventListener?.("arReady", schedule);
  };
}

/* ------------------------------------------------------------------ */
/* Renderer tuning                                                     */
/* ------------------------------------------------------------------ */

/**
 * Two cheap but large wins on older phones:
 *
 * 1. devicePixelRatio cap. A 3x-DPR budget phone renders ~9x the fragments of
 *    a 1x canvas for zero perceptible gain over a live camera feed. A-Frame
 *    defaults to the full device ratio; we clamp it per tier.
 * 2. Stop the render loop while the tab/app is backgrounded. Otherwise the
 *    GPU keeps drawing, drains battery and is the usual trigger for the
 *    "context lost" black screen when the OS reclaims memory.
 */
export function applyRendererTuning(scene: any, tier: DeviceTier): () => void {
  if (typeof window === "undefined") return () => {};
  const cap = DPR_CAP[tier];

  const clamp = () => {
    try {
      const renderer = scene?.renderer;
      if (!renderer) return;
      const dpr = Math.min(window.devicePixelRatio || 1, cap);
      if (Math.abs(renderer.getPixelRatio?.() - dpr) > 0.01) {
        renderer.setPixelRatio(dpr);
        scene.resize?.();
      }
    } catch {
      /* renderer torn down */
    }
  };

  scene?.addEventListener?.("renderstart", clamp);
  clamp();

  const onVis = () => {
    try {
      if (document.hidden) scene?.pause?.();
      else {
        scene?.play?.();
        clamp();
      }
    } catch {
      /* scene gone */
    }
  };
  document.addEventListener("visibilitychange", onVis);

  return () => {
    document.removeEventListener("visibilitychange", onVis);
    scene?.removeEventListener?.("renderstart", clamp);
  };
}

/* ------------------------------------------------------------------ */
/* VR support                                                          */
/* ------------------------------------------------------------------ */

/** Feature-detect a real immersive-vr session (headset present). */
export async function isImmersiveVrSupported(): Promise<boolean> {
  try {
    const xr = (navigator as any)?.xr;
    if (!xr?.isSessionSupported) return false;
    return (await xr.isSessionSupported("immersive-vr")) === true;
  } catch {
    return false;
  }
}

/** Hard stop for any camera stream still held by the page. */
export function releaseCameraStreams(root: ParentNode = document) {
  root.querySelectorAll("video").forEach((video) => {
    const stream = (video as HTMLVideoElement).srcObject;
    if (stream instanceof MediaStream) {
      stream.getTracks().forEach((t) => t.stop());
      (video as HTMLVideoElement).srcObject = null;
    }
  });
}

import { createServerFn } from "@tanstack/react-start";
import { z } from "zod";
import { requireSupabaseAuth } from "@/integrations/supabase/auth-middleware";

const CatalogInput = z.object({
  name: z.string().min(1).max(120),
  slug: z
    .string()
    .min(2)
    .max(80)
    .regex(/^[a-z0-9-]+$/i, "letters, numbers, dashes only"),
  is_active: z.boolean().default(true),
});

const CatalogItemInput = z.object({
  id: z.string().uuid().optional(),
  catalog_id: z.string().uuid(),
  name: z.string().min(1).max(120),
  sku: z.string().min(1).max(80),
  category: z.enum(["furniture", "paint", "flooring"]),
  glb_path: z.string().min(1),
  usdz_path: z.string().min(1),
  thumb_path: z.string().optional().nullable(),
  width_m: z.number().positive(),
  height_m: z.number().positive(),
  depth_m: z.number().positive(),
  color_hex: z.string().max(32).optional().nullable(),
  placement: z.enum(["floor", "wall"]),
  sort_order: z.number().int().min(0).default(0),
  is_active: z.boolean().default(true),
});

export const listCatalogs = createServerFn({ method: "GET" })
  .middleware([requireSupabaseAuth])
  .handler(async ({ context }) => {
    const { data, error } = await context.supabase
      .from("design_catalogs")
      .select("*")
      .order("created_at", { ascending: false });
    if (error) throw new Error(error.message);
    return data ?? [];
  });

export const createCatalog = createServerFn({ method: "POST" })
  .middleware([requireSupabaseAuth])
  .validator((raw) => CatalogInput.parse(raw))
  .handler(async ({ data, context }) => {
    const { data: row, error } = await context.supabase
      .from("design_catalogs")
      .insert({ ...data, owner_id: context.userId })
      .select()
      .single();
    if (error) throw new Error(error.message);
    return row;
  });

export const updateCatalog = createServerFn({ method: "POST" })
  .middleware([requireSupabaseAuth])
  .validator((raw) => CatalogInput.partial().extend({ id: z.string().uuid() }).parse(raw))
  .handler(async ({ data, context }) => {
    const { id, ...patch } = data;
    const { data: row, error } = await context.supabase
      .from("design_catalogs")
      .update(patch)
      .eq("id", id)
      .select()
      .single();
    if (error) throw new Error(error.message);
    return row;
  });

export const deleteCatalog = createServerFn({ method: "POST" })
  .middleware([requireSupabaseAuth])
  .validator((raw) => z.object({ id: z.string().uuid() }).parse(raw))
  .handler(async ({ data, context }) => {
    const { error } = await context.supabase.from("design_catalogs").delete().eq("id", data.id);
    if (error) throw new Error(error.message);
    return { ok: true };
  });

export const listCatalogItems = createServerFn({ method: "GET" })
  .validator((raw) => z.object({ catalogSlug: z.string().min(1) }).parse(raw ?? {}))
  .handler(async ({ data }) => {
    const { supabaseAdmin } = await import("@/integrations/supabase/client.server");
    const { createPresignedDownloadUrl } = await import("@/lib/storage.server");

    const { data: catalog } = (await supabaseAdmin
      .from("design_catalogs" as any)
      .select("id, slug")
      .eq("slug", data.catalogSlug)
      .eq("is_active", true)
      .maybeSingle()) as any;

    if (!catalog) return [] as any[];

    const { data: items, error } = (await supabaseAdmin
      .from("catalog_items" as any)
      .select("*")
      .eq("catalog_id", catalog.id)
      .eq("is_active", true)
      .order("sort_order", { ascending: true })) as any;
    if (error) throw new Error(error.message);

    const rows = items ?? [];
    const signed = await Promise.all(
      rows.map(async (row: any) => ({
        ...row,
        glb_url: row.glb_path ? await createPresignedDownloadUrl(row.glb_path, 15 * 60) : null,
        usdz_url: row.usdz_path ? await createPresignedDownloadUrl(row.usdz_path, 15 * 60) : null,
        thumb_url: row.thumb_path
          ? await createPresignedDownloadUrl(row.thumb_path, 15 * 60)
          : null,
      })),
    );

    return signed.map(({ glb_url, usdz_url, thumb_url, ...row }) => ({
      ...row,
      glb_url,
      usdz_url,
      thumb_url,
    }));
  });

export const saveCatalogItem = createServerFn({ method: "POST" })
  .middleware([requireSupabaseAuth])
  .validator((raw) => CatalogItemInput.parse(raw))
  .handler(async ({ data, context }) => {
    const { id, ...fields } = data;
    const table = () => context.supabase.from("catalog_items" as any) as any;

    if (id) {
      // Update in place. RLS scopes the row to the caller, so a foreign id
      // simply matches nothing instead of silently creating a duplicate.
      const { data: row, error } = await table()
        .update(fields)
        .eq("id", id)
        .select()
        .maybeSingle();
      if (error) throw new Error(error.message);
      if (!row) throw new Error("Catalog item not found or not editable by this account");
      return row;
    }

    const { data: row, error } = await table()
      .insert({ ...fields, owner_id: context.userId })
      .select()
      .single();
    if (error) throw new Error(error.message);
    return row;
  });

export const deleteCatalogItem = createServerFn({ method: "POST" })
  .middleware([requireSupabaseAuth])
  .validator((raw) => z.object({ id: z.string().uuid() }).parse(raw))
  .handler(async ({ data, context }) => {
    const { error } = await (context.supabase.from("catalog_items" as any) as any)
      .delete()
      .eq("id", data.id);
    if (error) throw new Error(error.message);
    return { ok: true };
  });

export const signCatalogUpload = createServerFn({ method: "POST" })
  .middleware([requireSupabaseAuth])
  .validator((raw) =>
    z
      .object({
        path: z.string().min(1),
        upsert: z.boolean().optional(),
        size: z.number().int().nonnegative().optional(),
      })
      .parse(raw),
  )
  .handler(async ({ data, context }) => {
    const { authorizeUploader, scopeUploadPath } = await import("@/lib/uploader-guard.server");
    const uploader = await authorizeUploader(context.supabase, context.userId);
    const scopedPath = scopeUploadPath(uploader, data.path);

    const { checkPresignLicence } = await import("@/lib/adapters/presign-gate.server");
    const gate = await checkPresignLicence("upload");
    if (!gate.ok) throw new Error(gate.message);

    const { supabaseAdmin } = await import("@/integrations/supabase/client.server");
    const { data: signed, error } = await supabaseAdmin.storage
      .from("ar-media")
      .createSignedUploadUrl(scopedPath, { upsert: data.upsert ?? true });
    if (error) throw new Error(error.message);
    return signed;
  });

export const logPlacement = createServerFn({ method: "POST" })
  .validator((raw) =>
    z
      .object({
        catalogItemId: z.string().uuid(),
        sessionId: z.string().min(6).max(64),
        placement: z.enum(["floor", "wall"]),
      })
      .parse(raw),
  )
  .handler(async ({ data }) => {
    const { supabaseAdmin } = await import("@/integrations/supabase/client.server");
    const { data: item } = (await supabaseAdmin
      .from("catalog_items" as any)
      .select("id, catalog_id")
      .eq("id", data.catalogItemId)
      .eq("is_active", true)
      .maybeSingle()) as any;

    if (!item) return { ok: false as const };

    const { error } = await supabaseAdmin.from("scan_events").insert({
      catalog_item_id: item.id,
      experience_id: null,
      album_id: null,
      event_type: "ar_place",
      session_id: data.sessionId,
      target_index: null,
      duration_ms: null,
      metadata: { placement: data.placement },
    });

    if (error) throw new Error(error.message);
    return { ok: true as const };
  });

import { createServerFn } from "@tanstack/react-start";
import { z } from "zod";
import { requireSupabaseAuth } from "@/integrations/supabase/auth-middleware";
import { requireAdmin } from "@/lib/admin-guard";

export type GateEventRow = {
  id: string;
  created_at: string;
  user_id: string | null;
  path: string;
  decision: string;
  reason: string;
  is_admin: boolean;
  approval: string | null;
  deployment_role: string;
  meta: string | null;
};

/**
 * Fire-and-forget writer used by the auth gate. Unauthenticated by
 * necessity (it also logs the "no session" redirect), so it validates its
 * input strictly and is rate limited inside recordGateEvent.
 */
export const logGateEvent = createServerFn({ method: "POST" })
  .validator((input: unknown) =>
    z
      .object({
        path: z.string().max(512),
        decision: z.enum(["allow", "redirect", "deny"]),
