/**
 * ============================================================================
 * AETHER AR — ENTERPRISE DTO SANITIZER & LEAST-PRIVILEGE SERIALIZER
 * ============================================================================
 *
 * Guarantees that internal hashes, secrets, and private metadata are stripped
 * before any database entity is serialized and sent to the client frontend.
 *
 * Fields NEVER allowed to leave the server:
 *  - `pin_hash`
 *  - `device_secret_hash`
 *  - `token_hash`
 *  - `nonce_hash`
 *  - `password_hash`
 *  - `service_role_key`
 * ============================================================================
 */

import type { Database } from "@/integrations/supabase/types";

type RawExperience = Database["public"]["Tables"]["ar_experiences"]["Row"];
type RawAlbum = Database["public"]["Tables"]["albums"]["Row"];
type RawLicense = Database["public"]["Tables"]["licenses"]["Row"];
type RawActivation = Database["public"]["Tables"]["license_activations"]["Row"];
type RawProfile = Database["public"]["Tables"]["profiles"]["Row"];

/** Sanitized Experience DTO */
export type ExperienceDTO = Omit<RawExperience, "pin_hash"> & {
  has_pin: boolean;
  cover_preview_url?: string | null;
};

/** Sanitized Album DTO */
export type AlbumDTO = Omit<RawAlbum, "pin_hash"> & {
  has_pin: boolean;
  ar_experiences?: Array<{ id: string; title: string; target_index: number | null }>;
};

/** Sanitized License DTO */
export type LicenseDTO = RawLicense;

/** Sanitized License Activation DTO */
export type ActivationDTO = Omit<RawActivation, "device_secret_hash">;

/** Sanitized User Profile DTO */
export type ProfileDTO = Pick<
  RawProfile,
  | "id"
  | "email"
  | "display_name"
  | "avatar_url"
  | "approval_status"
  | "storage_quota_bytes"
  | "created_at"
>;

/**
 * Sanitizes an AR experience entity, removing internal bcrypt pin_hash.
 */
export function sanitizeExperience(
  row: Partial<RawExperience> & Record<string, any>,
): ExperienceDTO {
  const { pin_hash, ...safe } = row;
  return {
    ...safe,
    has_pin: Boolean(pin_hash),
  } as ExperienceDTO;
}

/**
 * Sanitizes an Album entity, removing internal bcrypt pin_hash.
 */
export function sanitizeAlbum(row: Partial<RawAlbum> & Record<string, any>): AlbumDTO {
  const { pin_hash, ...safe } = row;
  return {
    ...safe,
    has_pin: Boolean(pin_hash),
  } as AlbumDTO;
}

/**
 * Sanitizes a License Activation entity, removing device_secret_hash.
 */
export function sanitizeActivation(
  row: Partial<RawActivation> & Record<string, any>,
): ActivationDTO {
  const { device_secret_hash, ...safe } = row;
  return safe as ActivationDTO;
}

/**
 * Sanitizes a User Profile entity, ensuring internal flags are stripped.
 */
export function sanitizeProfile(row: Partial<RawProfile> & Record<string, any>): ProfileDTO {
  return {
    id: row.id || "",
    email: row.email || null,
    display_name: row.display_name || null,
    avatar_url: row.avatar_url || null,
    approval_status: row.approval_status || "pending",
    storage_quota_bytes: Number(row.storage_quota_bytes || 0),
    created_at: row.created_at || new Date().toISOString(),
  };
}

export const sanitizeLicenseActivation = sanitizeActivation;
export const sanitizeProfilePublic = sanitizeProfile;

/**
 * ============================================================================
 * AETHER AR — ENTERPRISE STRUCTURED LOGGER & OBSERVABILITY
 * ============================================================================
 *
 * Provides structured JSON logging with Request ID correlation, automatic
 * sensitive data redaction (passwords, tokens, private keys), and user-safe
 * error normalization.
 * ============================================================================
 */

export type LogLevel = "info" | "warn" | "error" | "debug";

const SENSITIVE_KEYS = new Set([
  "password",
  "token",
  "secret",
  "authorization",
  "apikey",
  "key",
  "service_role",
  "private_key",
  "pin_hash",
  "device_secret",
  "cookie",
]);

/**
 * Recursively masks sensitive fields in metadata before logging.
 */
export function maskSensitiveData(obj: any): any {
  if (!obj || typeof obj !== "object") return obj;

  if (Array.isArray(obj)) {
    return obj.map((item) => maskSensitiveData(item));
  }

  const sanitized: Record<string, any> = {};
  for (const [key, value] of Object.entries(obj)) {
    const lowerKey = key.toLowerCase();
    const isSensitive = Array.from(SENSITIVE_KEYS).some((s) => lowerKey.includes(s));

    if (isSensitive && typeof value === "string") {
      sanitized[key] = value.length > 8 ? `${value.slice(0, 3)}***${value.slice(-3)}` : "********";
    } else if (typeof value === "object") {
      sanitized[key] = maskSensitiveData(value);
    } else {
      sanitized[key] = value;
    }
  }

  return sanitized;
}

export class EnterpriseLogger {
  private requestId: string;

  constructor(requestId?: string) {
    this.requestId = requestId || crypto.randomUUID();
  }

  private emit(level: LogLevel, event: string, metadata?: Record<string, any>) {
    const logEntry = {
      timestamp: new Date().toISOString(),
      level,
      requestId: this.requestId,
      event,
      meta: metadata ? maskSensitiveData(metadata) : undefined,
    };

    if (level === "error") {
      console.error(JSON.stringify(logEntry));
    } else if (level === "warn") {
      console.warn(JSON.stringify(logEntry));
    } else {
      console.log(JSON.stringify(logEntry));
    }
  }

  info(event: string, meta?: Record<string, any>) {
    this.emit("info", event, meta);
  }

  warn(event: string, meta?: Record<string, any>) {
    this.emit("warn", event, meta);
  }

  error(event: string, error?: Error | unknown, meta?: Record<string, any>) {
    const errMeta =
      error instanceof Error
        ? { message: error.message, stack: error.stack, ...meta }
        : { rawError: String(error), ...meta };
    this.emit("error", event, errMeta);
  }
  static forRequest(requestId?: string | Request): EnterpriseLogger {
    if (requestId instanceof Request) {
      return new EnterpriseLogger(getRequestId(requestId));
    }
    return new EnterpriseLogger(requestId);
  }
}

/** Extracts or generates a correlation ID from standard headers (Cloudflare Ray, X-Request-ID, Traceparent). */
export function getRequestId(request?: Request): string {
  if (!request) return crypto.randomUUID();
  return (
    request.headers.get("x-request-id") ||
    request.headers.get("cf-ray") ||
    request.headers.get("traceparent") ||
    crypto.randomUUID()
  );
}

/** Global default logger instance */
export const logger = new EnterpriseLogger();

/**
 * Normalizes internal errors into safe, client-facing JSON messages.
 */
export function normalizeUserError(error: unknown): { ok: false; error: string; code?: string } {
  if (error instanceof Error) {
    // Known user-safe messages
    if (
      error.message.includes("PIN") ||
      error.message.includes("limit") ||
      error.message.includes("Unauthorized")
    ) {
      return { ok: false, error: error.message };
    }
    logger.error("internal_unhandled_error", error);
    return { ok: false, error: "An unexpected error occurred. Please try again later." };
  }
  return { ok: false, error: "Bad request" };
}

import { createServerFn } from "@tanstack/react-start";
