export const Route = createFileRoute("/_authenticated/dashboard/activations")({
  beforeLoad: async () => {
    const ok = await assertAdmin()
      .then(() => true)
      .catch(() => false);
    if (!ok) {
      toast.error("You don't have access to device activations.");
      throw redirect({ to: "/dashboard" });
    }
  },
  component: ActivationsPage,
});

function ActivationsPage() {
  const qc = useQueryClient();
  const listFn = useServerFn(listActivations);
  const revokeFn = useServerFn(revokeActivation);
  const {
    data: activations = [],
    isLoading,
    error,
    refetch,
  } = useQuery({
    queryKey: ["activations"],
    queryFn: () => listFn(),
    staleTime: 30_000,
  });

  const releaseFn = useServerFn(forceReleaseActivation);
  const [target, setTarget] = useState<any | null>(null);
  const [password, setPassword] = useState("");
  const [reason, setReason] = useState("");
  const [lastEntry, setLastEntry] = useState<any | null>(null);

  const releaseMut = useMutation({
    mutationFn: () => releaseFn({ data: { id: target.id, password, reason: reason || undefined } }),
    onSuccess: (entry) => {
      qc.invalidateQueries({ queryKey: ["activations"] });
      setLastEntry(entry);
      setTarget(null);
      setPassword("");
      setReason("");
      toast.success("Device slot released — cooldown cleared.");
    },
    onError: (e: Error) => toast.error(e.message),
  });

  const revokeMut = useMutation({
    mutationFn: (id: string) => revokeFn({ data: { id } }),
    onSuccess: () => {
      qc.invalidateQueries({ queryKey: ["activations"] });
      toast.success("Revoked");
    },
  });

  return (
    <div className="p-8 max-w-6xl">
      <h1 className="text-3xl font-serif italic mb-1">Activations</h1>
      <p className="text-sm text-muted-foreground mb-8">
        Deployment instances that have activated a license.
      </p>

      <QueryState
        isLoading={isLoading}
        error={error}
        onRetry={() => refetch()}
        label="activations"
      />

      <div className="rounded-2xl border border-border/60 bg-card/40 overflow-hidden">
        <table className="w-full text-sm">
          <thead className="bg-muted/50 text-xs uppercase text-muted-foreground">
            <tr>
              <th className="text-left px-4 py-3">Client / License</th>
              <th className="text-left px-4 py-3">Deployment</th>
              <th className="text-left px-4 py-3">Fingerprint</th>
              <th className="text-left px-4 py-3">Last seen</th>
              <th className="text-left px-4 py-3">Status</th>
              <th />
            </tr>
          </thead>
          <tbody className="divide-y divide-border/60">
            {activations.map((a: any) => (
              <tr key={a.id}>
                <td className="px-4 py-3">
                  <div>{a.licenses?.client_name}</div>
                  <div className="text-xs font-mono text-muted-foreground">
                    {a.licenses?.license_key}
                  </div>
                </td>
                <td className="px-4 py-3">
                  <div>{a.deployment_domain || "—"}</div>
                  <div className="text-xs text-muted-foreground">{a.deployment_platform}</div>
                </td>
                <td className="px-4 py-3 font-mono text-xs">{a.fingerprint.slice(0, 16)}…</td>
                <td className="px-4 py-3 text-xs">{new Date(a.last_seen_at).toLocaleString()}</td>
                <td className="px-4 py-3">
                  {a.revoked_at ? (
                    <span className="text-xs text-destructive">Revoked</span>
                  ) : (
                    <span className="text-xs text-primary">Active</span>
                  )}
                </td>
                <td className="px-4 py-3">
                  <div className="flex items-center gap-2">
                    {!a.revoked_at && (
                      <button
                        onClick={() => confirm("Revoke this activation?") && revokeMut.mutate(a.id)}
                        className="inline-flex items-center gap-1 text-xs px-2 py-1 rounded-md border border-border hover:bg-destructive/10 text-destructive"
                      >
                        <ShieldOff className="h-3 w-3" /> Revoke
                      </button>
                    )}
                    <button
                      onClick={() => {
                        setTarget(a);
                        setPassword("");
                        setReason("");
                      }}
                      className="inline-flex items-center gap-1 text-xs px-2 py-1 rounded-md border border-border hover:bg-muted"
                      title="Free this slot immediately and clear the 12h cooldown"
                    >
                      <Unlock className="h-3 w-3" /> Force release
                    </button>
                  </div>
                </td>
              </tr>
            ))}
            {activations.length === 0 && (
              <tr>
                <td colSpan={6} className="px-4 py-12 text-center text-muted-foreground">
                  No activations yet.
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {lastEntry && (
        <div className="mt-6 rounded-2xl border border-border/60 bg-card/40 p-4">
          <div className="flex items-center gap-2 text-sm font-medium mb-2">
            <ScrollText className="h-4 w-4 text-primary" /> Audit entry recorded
          </div>
          <dl className="grid grid-cols-[auto_1fr] gap-x-4 gap-y-1 text-xs text-muted-foreground">
            <dt>Action</dt>
            <dd className="font-mono text-foreground">{lastEntry.action}</dd>
            <dt>Activation</dt>
            <dd className="font-mono">{lastEntry.target_id}</dd>
            <dt>When</dt>
            <dd>{new Date(lastEntry.created_at).toLocaleString()}</dd>
            <dt>Details</dt>
            <dd className="font-mono break-all">{JSON.stringify(lastEntry.metadata)}</dd>
          </dl>
        </div>
      )}

      {target && (
        <div className="fixed inset-0 z-50 bg-black/60 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="w-full max-w-md rounded-2xl border border-border/60 bg-card p-6">
            <div className="flex items-center justify-between mb-2">
              <h2 className="text-xl font-serif italic">Force-release device</h2>
              <button onClick={() => setTarget(null)} aria-label="Close">
                <X className="h-4 w-4" />
              </button>
            </div>
            <p className="text-sm text-muted-foreground mb-4">
              This frees the {target.device_class} slot on{" "}
              <span className="text-foreground">{target.licenses?.client_name}</span> straight away
              and skips the 12-hour cooldown. Confirm with your password.
            </p>
            <form
              onSubmit={(e) => {
                e.preventDefault();
                releaseMut.mutate();
              }}
              className="space-y-3"
            >
              <input
                required
                type="password"
                autoComplete="current-password"
                placeholder="Your password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="w-full rounded-md border border-border bg-background px-3 py-2 text-sm"
              />
              <input
                placeholder="Reason (kept in the audit log)"
                value={reason}
                onChange={(e) => setReason(e.target.value)}
                className="w-full rounded-md border border-border bg-background px-3 py-2 text-sm"
              />
              <button
                disabled={releaseMut.isPending}
                className="w-full rounded-md bg-primary text-primary-foreground px-4 py-2 text-sm font-medium hover:bg-primary/90 disabled:opacity-50"
              >
                {releaseMut.isPending ? "Releasing…" : "Confirm release"}
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

import { createFileRoute, Link } from "@tanstack/react-router";
import { useServerFn } from "@tanstack/react-start";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { useState } from "react";
import {
  listMyAlbums,
  deleteAlbum,
  setAlbumPublished,
  setAlbumGalleryVisibility,
} from "@/lib/albums.functions";
import { QueryState } from "@/components/QueryState";
import { QRCodeDialog } from "@/components/QRCodeDialog";
import { Images, Plus, QrCode, Trash2, Eye, EyeOff } from "lucide-react";
import { toast } from "sonner";

export const Route = createFileRoute("/_authenticated/dashboard/albums/")({
  component: AlbumsPage,
});

function AlbumsPage() {
  const qc = useQueryClient();
  const list = useServerFn(listMyAlbums);
  const del = useServerFn(deleteAlbum);
  const publish = useServerFn(setAlbumPublished);
  const setGallery = useServerFn(setAlbumGalleryVisibility);
  const [qr, setQr] = useState<{ id: string; slug: string; title: string } | null>(null);

  const query = useQuery({
    queryKey: ["albums"],
    queryFn: () => list(),
    staleTime: 30_000,
  });

  const delMut = useMutation({
    mutationFn: (id: string) => del({ data: { id } }),
    onSuccess: () => {
      toast.success("Album deleted");
      qc.invalidateQueries({ queryKey: ["albums"] });
    },
    onError: (e: any) => toast.error(e.message ?? "Delete failed"),
  });

  const pubMut = useMutation({
    mutationFn: (v: { id: string; published: boolean }) => publish({ data: v }),
    onSuccess: () => qc.invalidateQueries({ queryKey: ["albums"] }),
    onError: (e: any) => toast.error(e.message ?? "Update failed"),
  });

  const galleryMut = useMutation({
    mutationFn: (v: { id: string; show: boolean }) => setGallery({ data: v }),
    onSuccess: () => qc.invalidateQueries({ queryKey: ["albums"] }),
    onError: (e: any) => toast.error(e.message ?? "Update failed"),
  });

  return (
    <div className="p-4 md:p-8 max-w-5xl">
      <div className="flex flex-wrap items-center justify-between gap-3 mb-2">
        <h1 className="text-2xl md:text-3xl font-serif italic">Albums</h1>
        <Link
          to="/dashboard/albums/new"
          className="inline-flex items-center gap-2 rounded-md bg-primary text-primary-foreground px-4 py-2 text-sm hover:bg-primary/90"
        >
          <Plus className="h-4 w-4" /> New album
        </Link>
      </div>
      <p className="text-sm text-muted-foreground mb-6">
        One QR code per album. Customers scan once, then point their camera at any photo in the
        album to play that photo's video.
      </p>

      <QueryState
        isLoading={query.isPending}
        error={query.error}
        onRetry={() => query.refetch()}
        label="albums"
      />

      {query.data &&
        (query.data.length === 0 ? (
          <div className="rounded-xl border border-dashed border-border/60 p-10 text-center text-sm text-muted-foreground">
            <Images className="h-6 w-6 mx-auto mb-3 opacity-60" />
            No albums yet. Create one to generate a single album QR code.
          </div>
        ) : (
          <div className="space-y-3">
            {query.data.map((a) => (
              <div
                key={a.id}
                className="rounded-xl border border-border/60 bg-card/40 p-4 flex flex-wrap items-center gap-3"
              >
                <div className="min-w-0 flex-1">
                  <p className="font-medium truncate">{a.title}</p>
                  <p className="text-xs text-muted-foreground truncate">
                    /ar/album/{a.slug} · {a.target_count} photo
                    {a.target_count === 1 ? "" : "s"}
                  </p>
                </div>
                <button
                  onClick={() => pubMut.mutate({ id: a.id, published: !a.published })}
                  className={`rounded-full px-3 py-1 text-xs border ${
                    a.published
                      ? "border-primary/40 text-primary bg-primary/10"
                      : "border-border text-muted-foreground"
                  }`}
                >
                  {a.published ? "Published" : "Draft"}
                </button>
                <button
                  disabled={galleryMut.isPending}
                  onClick={() => galleryMut.mutate({ id: a.id, show: !a.show_in_gallery })}
                  title={
                    a.show_in_gallery
                      ? "Listed in the public gallery"
                      : "Hidden from the public gallery"
                  }
                  className={`inline-flex items-center gap-1.5 rounded-full px-3 py-1 text-xs border disabled:opacity-50 ${
                    a.show_in_gallery
                      ? "border-primary/40 text-primary bg-primary/10"
                      : "border-border text-muted-foreground"
                  }`}
                >
                  {a.show_in_gallery ? (
                    <Eye className="h-3.5 w-3.5" />
                  ) : (
                    <EyeOff className="h-3.5 w-3.5" />
                  )}
                  Gallery
                </button>
                <button
                  onClick={() => setQr({ id: a.id, slug: a.slug, title: a.title })}
                  className="inline-flex items-center gap-2 rounded-md border border-border px-3 py-1.5 text-xs hover:bg-accent"
                >
                  <QrCode className="h-3.5 w-3.5" /> QR
                </button>
                <button
                  onClick={() => {
                    if (confirm(`Delete "${a.title}" and its photos?`)) delMut.mutate(a.id);
                  }}
                  className="inline-flex items-center gap-2 rounded-md border border-destructive/40 text-destructive px-3 py-1.5 text-xs hover:bg-destructive/10"
                >
                  <Trash2 className="h-3.5 w-3.5" />
                </button>
              </div>
            ))}
          </div>
        ))}

      {qr && (
        <QRCodeDialog
          id={qr.id}
          slug={qr.slug}
          title={qr.title}
          kind="album"
          onSlugChange={() => qc.invalidateQueries({ queryKey: ["albums"] })}
          onClose={() => setQr(null)}
        />
      )}
    </div>
  );
}

import { createFileRoute, useNavigate } from "@tanstack/react-router";
import { useServerFn } from "@tanstack/react-start";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { useRef, useState } from "react";
import { compileAlbumTargets } from "@/lib/mindar-compiler";
import { uploadToArMedia } from "@/lib/upload";
import { createAlbum, MAX_ALBUM_TARGETS } from "@/lib/albums.functions";
import { listMyExperiences, signMyExperienceAssets } from "@/lib/experiences.functions";
import { AlertTriangle, Images, Library, Loader2, Upload, X } from "lucide-react";
import { toast } from "sonner";

export const Route = createFileRoute("/_authenticated/dashboard/albums/new")({
  component: NewAlbumPage,
});

interface Photo {
  file: File;
  previewUrl: string;
  title: string;
  video: File | null;
  /** When reused from an existing AR experience, its already-stored assets. */
  existing?: {
    marker_path: string;
    media_path: string;
    media_type: "video" | "image";
    label: string;
  };
}

function slugify(v: string) {
  return v
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 80);
}

function errText(e: any) {
  if (!e) return "Unknown error";
  if (typeof e === "string") return e;
  if (Array.isArray(e?.issues))
    return e.issues.map((i: any) => `${i.path?.join(".") || "field"}: ${i.message}`).join(" · ");
  return e?.message ?? JSON.stringify(e);
}

function NewAlbumPage() {
  const navigate = useNavigate();
  const qc = useQueryClient();
  const create = useServerFn(createAlbum);
  const fetchExperiences = useServerFn(listMyExperiences);
  const signAssets = useServerFn(signMyExperienceAssets);
  const fileRef = useRef<HTMLInputElement>(null);

  const [title, setTitle] = useState("");
  const [slug, setSlug] = useState("");
  const [photos, setPhotos] = useState<Photo[]>([]);
  const [compileProgress, setCompileProgress] = useState<number | null>(null);
  const [saving, setSaving] = useState(false);
  const [stage, setStage] = useState<string>("");
  const [saveError, setSaveError] = useState<string | null>(null);
  const [pickerOpen, setPickerOpen] = useState(false);
  const [importing, setImporting] = useState<string | null>(null);

  const atCap = photos.length >= MAX_ALBUM_TARGETS;

  const experiences = useQuery({
    queryKey: ["experiences"],
    queryFn: () => fetchExperiences(),
    enabled: pickerOpen,
  });

  function addFiles(files: FileList) {
    const incoming = Array.from(files).filter((f) => f.type.startsWith("image/"));
    const room = MAX_ALBUM_TARGETS - photos.length;
    if (incoming.length > room) {
      toast.error(
        `Albums are limited to ${MAX_ALBUM_TARGETS} photos for reliable AR tracking — create a second album for additional photos.`,
      );
    }
    const accepted = incoming.slice(0, Math.max(0, room)).map((file) => ({
      file,
      previewUrl: URL.createObjectURL(file),
      title: file.name.replace(/\.[^.]+$/, ""),
      video: null as File | null,
    }));
    setPhotos((p) => [...p, ...accepted]);
  }

  /** Pull a photo + video straight out of an existing AR experience. */
  async function importExperience(id: string) {
    if (atCap) return toast.error("Album is at its photo cap");
    setImporting(id);
    try {
      const info = await signAssets({ data: { id } });
      if (!info.marker_signed_url) throw new Error("Could not read that experience's marker image");
      const res = await fetch(info.marker_signed_url);
      if (!res.ok) throw new Error("Could not download the marker image");
      const blob = await res.blob();
      const ext = info.marker_path.split(".").pop() || "jpg";
      const file = new File([blob], `${slugify(info.title)}.${ext}`, {
        type: blob.type || "image/jpeg",
      });
      setPhotos((p) => [
        ...p,
        {
          file,
          previewUrl: URL.createObjectURL(file),
          title: info.title,
          video: null,
          existing: {
            marker_path: info.marker_path,
            media_path: info.media_path,
            media_type: info.media_type,
            label: info.title,
          },
        },
      ]);
      setPickerOpen(false);
    } catch (e: any) {
      toast.error(errText(e));
    } finally {
      setImporting(null);
    }
  }

  function update(i: number, patch: Partial<Photo>) {
    setPhotos((p) => p.map((ph, idx) => (idx === i ? { ...ph, ...patch } : ph)));
  }

  function remove(i: number) {
    setPhotos((p) => {
      URL.revokeObjectURL(p[i].previewUrl);
      return p.filter((_, idx) => idx !== i);
    });
  }

  async function save() {
    setSaveError(null);
    const finalSlug = slugify(slug || title);
    if (!title.trim()) return setSaveError("Album name is required");
    if (finalSlug.length < 2) return setSaveError("Album link must be at least 2 characters");
    if (photos.length === 0) return setSaveError("Add at least one photo");
    if (photos.length > MAX_ALBUM_TARGETS)
      return setSaveError(
        `Albums are limited to ${MAX_ALBUM_TARGETS} photos for reliable AR tracking — create a second album for additional photos.`,
      );
    const missing = photos.findIndex((p) => !p.video && !p.existing);
    if (missing !== -1)
      return setSaveError(
        `Photo ${missing + 1} has no video yet — upload one or import an existing experience.`,
      );

    setSaving(true);
    try {
      setStage("Compiling AR targets…");
      setCompileProgress(0);
      const mindBlob = await compileAlbumTargets(
        photos.map((p) => p.file),
        setCompileProgress,
      );
      setCompileProgress(100);

      setStage("Uploading compiled marker…");
      const compiled_mind_path = await uploadToArMedia(mindBlob, "markers", `${finalSlug}.mind`);

      const targets = [];
      for (let i = 0; i < photos.length; i++) {
        const p = photos[i];
        setStage(`Preparing photo ${i + 1} of ${photos.length}…`);
        const marker_path = p.existing?.marker_path ?? (await uploadToArMedia(p.file, "markers"));
        const media_path =
          p.existing && !p.video ? p.existing.media_path : await uploadToArMedia(p.video!, "media");
        targets.push({
          title: p.title || `Photo ${i + 1}`,
          marker_path,
          media_path,
          media_type: (p.video ? "video" : (p.existing?.media_type ?? "video")) as
            | "video"
            | "image",
          autoplay: true,
          loop_playback: true,
        });
      }

      setStage("Saving album…");
      await create({
        data: {
          title: title.trim(),
          slug: finalSlug,
          compiled_mind_path,
          published: true,
          targets,
        },
      });

      qc.invalidateQueries({ queryKey: ["albums"] });
      toast.success("Album created — one QR code covers all photos");
      navigate({ to: "/dashboard/albums" });
    } catch (e: any) {
      console.error("Album save failed", e);
      setSaveError(errText(e));
      toast.error(errText(e));
    } finally {
      setSaving(false);
      setCompileProgress(null);
      setStage("");
    }
  }

  return (
    <div className="p-4 md:p-8 max-w-3xl">
      <h1 className="text-2xl md:text-3xl font-serif italic mb-1">New album</h1>
      <p className="text-sm text-muted-foreground mb-6">
        Upload up to {MAX_ALBUM_TARGETS} photos (or reuse existing AR experiences), assign a video
        to each, and we'll compile them into a single AR marker file. One QR code covers the whole
        album.
      </p>

      <div className="grid gap-4 sm:grid-cols-2 mb-6">
        <label className="block">
          <span className="text-xs text-muted-foreground">Album name</span>
          <input
            value={title}
            onChange={(e) => {
              setTitle(e.target.value);
              if (!slug) setSlug(slugify(e.target.value));
            }}
            placeholder="Priya & Arjun — Wedding"
            className="mt-1 w-full rounded-md border border-border bg-background px-3 py-2 text-sm"
          />
        </label>
        <label className="block">
          <span className="text-xs text-muted-foreground">Album link</span>
          <input
            value={slug}
            onChange={(e) => setSlug(slugify(e.target.value))}
            placeholder="priya-arjun-wedding"
            className="mt-1 w-full rounded-md border border-border bg-background px-3 py-2 text-sm font-mono"
          />
        </label>
      </div>

      <div className="mb-4 flex flex-wrap items-center gap-3">
        <button
          type="button"
          onClick={() => fileRef.current?.click()}
          disabled={atCap || saving}
          className="inline-flex items-center gap-2 rounded-md border border-dashed border-border px-4 py-2 text-sm hover:bg-accent disabled:opacity-50"
        >
          <Upload className="h-4 w-4" /> Add photos
        </button>
        <button
          type="button"
          onClick={() => setPickerOpen((v) => !v)}
          disabled={atCap || saving}
          className="inline-flex items-center gap-2 rounded-md border border-border px-4 py-2 text-sm hover:bg-accent disabled:opacity-50"
        >
          <Library className="h-4 w-4" /> Use existing experience
        </button>
        <span className="text-xs text-muted-foreground">
          {photos.length} / {MAX_ALBUM_TARGETS} photos
        </span>
        <input
          ref={fileRef}
          type="file"
          accept="image/*"
          multiple
          className="hidden"
          onChange={(e) => {
            if (e.target.files) addFiles(e.target.files);
            e.target.value = "";
          }}
        />
      </div>

      {pickerOpen && (
        <div className="mb-4 rounded-xl border border-border/60 bg-card/40 p-3">
          <p className="mb-2 text-xs text-muted-foreground">
            Pick an AR experience — its marker photo and video are reused, so nothing is uploaded
            twice.
          </p>
          {experiences.isLoading && (
            <p className="text-xs text-muted-foreground">Loading experiences…</p>
          )}
          {experiences.error && (
            <p className="text-xs text-destructive">{errText(experiences.error)}</p>
          )}
          {experiences.data && experiences.data.length === 0 && (
            <p className="text-xs text-muted-foreground">No AR experiences yet.</p>
          )}
          <ul className="grid gap-2 sm:grid-cols-2">
            {(experiences.data ?? [])
              .filter((x: any) => x.marker_path && x.media_path)
              .map((x: any) => (
                <li key={x.id}>
                  <button
                    type="button"
                    onClick={() => importExperience(x.id)}
                    disabled={!!importing || atCap}
                    className="flex w-full items-center gap-3 rounded-lg border border-border/60 px-3 py-2 text-left text-xs hover:bg-accent disabled:opacity-50"
                  >
                    {x.cover_preview_url ? (
                      <img
                        src={x.cover_preview_url}
                        alt=""
                        className="h-10 w-10 shrink-0 rounded object-cover"
                      />
                    ) : (
                      <span className="grid h-10 w-10 shrink-0 place-items-center rounded bg-muted">
                        <Images className="h-4 w-4 opacity-60" />
                      </span>
                    )}
                    <span className="min-w-0 flex-1 truncate">{x.title}</span>
                    {importing === x.id && <Loader2 className="h-3.5 w-3.5 animate-spin" />}
                  </button>
                </li>
              ))}
          </ul>
        </div>
      )}

      {atCap && (
        <div className="mb-4 flex items-start gap-2 rounded-md border border-amber-500/40 bg-amber-500/10 px-3 py-2 text-xs">
          <AlertTriangle className="h-4 w-4 shrink-0 text-amber-500" />
          Albums are limited to {MAX_ALBUM_TARGETS} photos for reliable AR tracking — create a
          second album (and QR code) for additional photos.
        </div>
      )}

      {photos.length === 0 ? (
        <div className="rounded-xl border border-dashed border-border/60 p-10 text-center text-sm text-muted-foreground">
          <Images className="h-6 w-6 mx-auto mb-3 opacity-60" />
          No photos yet. Upload the printed photos customers will point their camera at.
        </div>
      ) : (
        <ol className="space-y-3">
          {photos.map((p, i) => (
            <li
              key={i}
              className="rounded-xl border border-border/60 bg-card/40 p-3 flex gap-3 items-start"
            >
              <img
                src={p.previewUrl}
                alt=""
                className="h-20 w-20 rounded-md object-cover shrink-0"
              />
              <div className="min-w-0 flex-1 space-y-2">
                <div className="flex items-center gap-2">
                  <span className="rounded-full bg-primary/15 text-primary px-2 py-0.5 text-[11px]">
                    Target {i + 1}
                  </span>
                  {p.existing && (
                    <span className="rounded-full bg-muted px-2 py-0.5 text-[11px] text-muted-foreground">
                      From experience
                    </span>
                  )}
                  <button
                    onClick={() => remove(i)}
                    disabled={saving}
                    className="ml-auto p-1 rounded-md hover:bg-accent"
                    aria-label="Remove photo"
                  >
                    <X className="h-3.5 w-3.5" />
                  </button>
                </div>
                <input
                  value={p.title}
                  onChange={(e) => update(i, { title: e.target.value })}
                  placeholder="Photo title"
                  className="w-full rounded-md border border-border bg-background px-3 py-1.5 text-xs"
                />
                <label className="block">
                  <span className="text-[11px] text-muted-foreground">
                    {p.existing
                      ? "Video (already attached — upload to replace)"
                      : "Video for this photo"}
                  </span>
                  <input
                    type="file"
                    accept="video/*"
                    onChange={(e) => update(i, { video: e.target.files?.[0] ?? null })}
                    className="mt-1 block w-full text-xs file:mr-3 file:rounded-md file:border file:border-border file:bg-background file:px-2 file:py-1 file:text-xs"
                  />
                </label>
                {p.video ? (
                  <p className="text-[11px] text-muted-foreground truncate">
                    {p.video.name} · {(p.video.size / 1048576).toFixed(1)} MB
                  </p>
                ) : p.existing ? (
                  <p className="text-[11px] text-muted-foreground truncate">
                    Reusing video from “{p.existing.label}”
                  </p>
                ) : null}
              </div>
            </li>
          ))}
        </ol>
      )}

      {saveError && (
        <div className="mt-6 flex items-start gap-2 rounded-md border border-destructive/40 bg-destructive/10 px-3 py-2 text-xs text-destructive">
          <AlertTriangle className="mt-0.5 h-4 w-4 shrink-0" />
          <span className="break-words">{saveError}</span>
        </div>
      )}

      <div className="mt-6 flex items-center gap-3">
        <button
          onClick={save}
          disabled={saving}
          className="inline-flex items-center gap-2 rounded-md bg-primary text-primary-foreground px-5 py-2.5 text-sm hover:bg-primary/90 disabled:opacity-50"
        >
          {saving && <Loader2 className="h-4 w-4 animate-spin" />}
          {saving ? "Working…" : "Compile & create album"}
        </button>
        {stage && (
          <span className="text-xs text-muted-foreground">
            {stage}
            {compileProgress !== null && compileProgress < 100 ? ` ${compileProgress}%` : ""}
          </span>
        )}
      </div>
    </div>
  );
}

import { createFileRoute, redirect } from "@tanstack/react-router";
import { useServerFn } from "@tanstack/react-start";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { useState } from "react";
import { toast } from "sonner";
import { QueryState } from "@/components/QueryState";
import { assertAdmin } from "@/lib/admin.functions";
import { listAccounts, decideAccount } from "@/lib/approvals.functions";
import { Check, Clock, X } from "lucide-react";

export const Route = createFileRoute("/_authenticated/dashboard/approvals")({
  beforeLoad: async () => {
    const ok = await assertAdmin()
      .then(() => true)
      .catch(() => false);
    if (!ok) {
      toast.error("You don't have access to account approvals.");
      throw redirect({ to: "/dashboard" });
    }
  },
  component: ApprovalsPage,
});

const STATUS_STYLES: Record<string, string> = {
  approved: "bg-emerald-500/15 text-emerald-400",
  pending: "bg-amber-500/15 text-amber-400",
  rejected: "bg-destructive/15 text-destructive",
};

function ApprovalsPage() {
  const qc = useQueryClient();
  const listFn = useServerFn(listAccounts);
  const decideFn = useServerFn(decideAccount);
  const [filter, setFilter] = useState<"pending" | "all">("pending");

  const {
    data: accounts = [],
    isLoading,
    error,
    refetch,
  } = useQuery({
    queryKey: ["accounts"],
    queryFn: () => listFn(),
    staleTime: 15_000,
  });

  const decide = useMutation({
    mutationFn: (vars: { userId: string; decision: "approved" | "rejected"; reason?: string }) =>
      decideFn({ data: vars }),
    onSuccess: (res, vars) => {
      qc.invalidateQueries({ queryKey: ["accounts"] });
      qc.invalidateQueries({ queryKey: ["licenses"] });
      if (vars.decision === "approved") {
        toast.success(
          res?.license?.license_key
            ? `Approved — licence ${res.license.license_key} issued`
            : "Account approved",
        );
      } else {
        toast.success("Account rejected");
      }
    },
    onError: (e: any) => toast.error(e?.message ?? "Could not update the account"),
  });

  const rows = accounts.filter((a: any) =>
    filter === "pending" ? a.approval_status === "pending" : true,
  );
  const pendingCount = accounts.filter((a: any) => a.approval_status === "pending").length;

  return (
    <div className="p-8 max-w-6xl">
      <div className="flex flex-wrap items-start justify-between gap-4 mb-8">
        <div>
          <h1 className="text-2xl font-serif mb-1">Account approvals</h1>
          <p className="text-sm text-muted-foreground">
            New sign-ups stay locked until you approve them. Approving grants editor access and
            auto-issues that client's licence key.
          </p>
        </div>
        <div className="flex items-center gap-2">
          {pendingCount > 0 && (
            <span className="inline-flex items-center gap-1.5 rounded-full bg-amber-500/15 text-amber-400 px-3 py-1 text-xs">
              <Clock className="h-3.5 w-3.5" /> {pendingCount} waiting
            </span>
          )}
          <button
            onClick={() => setFilter(filter === "pending" ? "all" : "pending")}
            className="rounded-full border border-border/60 px-4 py-1.5 text-xs hover:bg-accent"
          >
            {filter === "pending" ? "Show all accounts" : "Show pending only"}
          </button>
        </div>
      </div>

      <QueryState isLoading={isLoading} error={error} onRetry={refetch} />

      {!isLoading && !error && (
        <div className="rounded-xl border border-border/60 overflow-x-auto">
          <table className="w-full text-sm">
            <thead className="bg-card/40 text-left text-xs uppercase tracking-wider text-muted-foreground">
              <tr>
                <th className="px-4 py-3">Account</th>
                <th className="px-4 py-3">Status</th>
                <th className="px-4 py-3">Licence</th>
                <th className="px-4 py-3">Actions</th>
              </tr>
            </thead>
            <tbody>
              {rows.length === 0 && (
                <tr>
                  <td colSpan={4} className="px-4 py-8 text-center text-muted-foreground">
                    {filter === "pending"
                      ? "No accounts waiting for approval."
                      : "No accounts yet."}
                  </td>
                </tr>
              )}
              {rows.map((a: any) => (
                <tr key={a.id} className="border-t border-border/60">
                  <td className="px-4 py-3">
                    <div className="font-medium">{a.display_name ?? "—"}</div>
                    <div className="text-xs text-muted-foreground">{a.email}</div>
                  </td>
                  <td className="px-4 py-3">
                    <span
                      className={`rounded-full px-2.5 py-1 text-xs ${
                        STATUS_STYLES[a.approval_status] ?? ""
                      }`}
                    >
                      {a.approval_status}
                    </span>
                    {a.approval_status === "rejected" && a.rejection_reason && (
                      <div className="mt-1 text-xs text-muted-foreground">{a.rejection_reason}</div>
                    )}
                  </td>
                  <td className="px-4 py-3">
                    {a.license ? (
                      <div>
                        <code className="text-xs">{a.license.license_key}</code>
                        <div className="text-xs text-muted-foreground">{a.license.status}</div>
                      </div>
                    ) : (
                      <span className="text-xs text-muted-foreground">—</span>
                    )}
                  </td>
                  <td className="px-4 py-3">
                    <div className="flex gap-2">
                      {a.approval_status !== "approved" && (
                        <button
                          disabled={decide.isPending}
                          onClick={() => decide.mutate({ userId: a.id, decision: "approved" })}
                          className="inline-flex items-center gap-1.5 rounded-full bg-primary text-primary-foreground px-3 py-1.5 text-xs disabled:opacity-50"
                        >
                          <Check className="h-3.5 w-3.5" /> Approve
                        </button>
                      )}
                      {a.approval_status !== "rejected" && (
                        <button
                          disabled={decide.isPending}
                          onClick={() => {
                            const reason =
                              window.prompt("Reason for rejection (shown to the user):") ?? "";
                            decide.mutate({ userId: a.id, decision: "rejected", reason });
                          }}
                          className="inline-flex items-center gap-1.5 rounded-full border border-border/60 px-3 py-1.5 text-xs hover:bg-accent disabled:opacity-50"
                        >
                          <X className="h-3.5 w-3.5" /> Reject
                        </button>
                      )}
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

