        </div>
      )}
    </div>
  );
}

import { createFileRoute } from "@tanstack/react-router";
import { useServerFn } from "@tanstack/react-start";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { useEffect, useRef, useState } from "react";
import {
  CALIBRATION_STEPS,
  listMarkerTests,
  recordMarkerTest,
  deleteMarkerTest,
} from "@/lib/marker-tests.functions";
import { listMyAlbums } from "@/lib/albums.functions";
import { QueryState } from "@/components/QueryState";
import { CheckCircle2, CircleAlert, Play, Square, Trash2, XCircle } from "lucide-react";
import { toast } from "sonner";

export const Route = createFileRoute("/_authenticated/dashboard/marker-tests")({
  head: () => ({
    meta: [
      { title: "Marker Accuracy Testing — Aether AR" },
      {
        name: "description",
        content:
          "Run guided real-world AR marker calibration steps and record scan outcomes per print.",
      },
    ],
  }),
  component: MarkerTestsPage,
});

type Outcome = "success" | "partial" | "fail";

function MarkerTestsPage() {
  const qc = useQueryClient();
  const list = useServerFn(listMarkerTests);
  const albumsFn = useServerFn(listMyAlbums);
  const record = useServerFn(recordMarkerTest);
  const del = useServerFn(deleteMarkerTest);

  const tests = useQuery({
    queryKey: ["marker-tests"],
    queryFn: () => list(),
    staleTime: 15_000,
  });
  const albums = useQuery({
    queryKey: ["albums"],
    queryFn: () => albumsFn(),
    staleTime: 60_000,
  });

  const [stepIdx, setStepIdx] = useState(0);
  const [albumId, setAlbumId] = useState<string>("");
  const [markerLabel, setMarkerLabel] = useState("");
  const [device, setDevice] = useState("");
  const [notes, setNotes] = useState("");
  const [elapsed, setElapsed] = useState<number | null>(null);
  const [running, setRunning] = useState(false);
  const startRef = useRef<number | null>(null);

  useEffect(() => {
    if (typeof navigator !== "undefined" && !device) {
      setDevice(navigator.userAgent.slice(0, 100));
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    if (!running) return;
    const id = setInterval(() => {
      if (startRef.current) setElapsed(Date.now() - startRef.current);
    }, 100);
    return () => clearInterval(id);
  }, [running]);

  const step = CALIBRATION_STEPS[stepIdx];

  const save = useMutation({
    mutationFn: (outcome: Outcome) =>
      record({
        data: {
          album_id: albumId || null,
          marker_label: markerLabel.trim() || "Untitled print",
          step_key: step.key,
          lighting: step.lighting,
          distance_cm: step.distance_cm,
          angle_deg: step.angle_deg,
          device: device || null,
          outcome,
          time_to_detect_ms: elapsed,
          notes: notes.trim() || null,
        },
      }),
    onSuccess: () => {
      toast.success("Result recorded");
      setNotes("");
      setElapsed(null);
      setRunning(false);
      startRef.current = null;
      qc.invalidateQueries({ queryKey: ["marker-tests"] });
      setStepIdx((i) => Math.min(i + 1, CALIBRATION_STEPS.length - 1));
    },
    onError: (e: any) => toast.error(e?.message ?? "Could not save result"),
  });

  const delMut = useMutation({
    mutationFn: (id: string) => del({ data: { id } }),
    onSuccess: () => qc.invalidateQueries({ queryKey: ["marker-tests"] }),
    onError: (e: any) => toast.error(e?.message ?? "Delete failed"),
  });

  const rows = tests.data ?? [];
  const total = rows.length;
  const ok = rows.filter((r: any) => r.outcome === "success").length;
  const successRate = total ? Math.round((ok / total) * 100) : 0;

  return (
    <div className="p-4 md:p-8 max-w-5xl">
      <h1 className="text-2xl md:text-3xl font-serif italic mb-1">Marker accuracy testing</h1>
      <p className="text-sm text-muted-foreground mb-6">
        Work through the guided steps with a real printed photo and record what actually happened.
        Results build your reliability baseline per print.
      </p>

      <div className="grid gap-4 sm:grid-cols-3 mb-6">
        <Stat label="Runs recorded" value={String(total)} />
        <Stat label="Success rate" value={`${successRate}%`} />
        <Stat
          label="Failures"
          value={String(rows.filter((r: any) => r.outcome === "fail").length)}
        />
      </div>

      <div className="rounded-2xl border border-border/60 bg-card/40 p-4 md:p-6 mb-8">
        <div className="flex flex-wrap gap-1.5 mb-4">
          {CALIBRATION_STEPS.map((s, i) => (
            <button
              key={s.key}
              onClick={() => setStepIdx(i)}
              className={`rounded-full px-3 py-1 text-xs transition-colors ${
                i === stepIdx
                  ? "bg-primary text-primary-foreground"
                  : "bg-accent text-muted-foreground hover:text-foreground"
              }`}
            >
              {s.title}
            </button>
          ))}
        </div>

        <h2 className="text-lg font-medium mb-1">{step.title}</h2>
        <p className="text-sm text-muted-foreground mb-4">{step.instruction}</p>

        <div className="grid gap-3 sm:grid-cols-2 mb-4">
          <label className="text-sm">
            <span className="block text-xs text-muted-foreground mb-1">Print / marker label</span>
            <input
              value={markerLabel}
              onChange={(e) => setMarkerLabel(e.target.value)}
              placeholder="e.g. Wedding album — page 3, glossy 6×4"
              className="w-full rounded-md border border-border/60 bg-background px-3 py-2 text-sm"
            />
          </label>
          <label className="text-sm">
            <span className="block text-xs text-muted-foreground mb-1">Album (optional)</span>
            <select
              value={albumId}
              onChange={(e) => setAlbumId(e.target.value)}
              className="w-full rounded-md border border-border/60 bg-background px-3 py-2 text-sm"
            >
              <option value="">— none —</option>
              {(albums.data ?? []).map((a: any) => (
                <option key={a.id} value={a.id}>
                  {a.title}
                </option>
              ))}
            </select>
          </label>
        </div>

        <div className="flex flex-wrap items-center gap-3 mb-4">
          <button
            onClick={() => {
              if (running) {
                setRunning(false);
              } else {
                startRef.current = Date.now();
                setElapsed(0);
                setRunning(true);
              }
            }}
            className="inline-flex items-center gap-2 rounded-md border border-border/60 px-3 py-2 text-sm hover:bg-accent"
          >
            {running ? <Square className="h-4 w-4" /> : <Play className="h-4 w-4" />}
            {running ? "Stop timer" : "Start detect timer"}
          </button>
          <span className="text-sm tabular-nums text-muted-foreground">
            {elapsed === null ? "—" : `${(elapsed / 1000).toFixed(1)}s to detect`}
          </span>
        </div>

        <textarea
          value={notes}
          onChange={(e) => setNotes(e.target.value)}
          rows={2}
          placeholder="What happened? jitter, wrong photo matched, needed a second try…"
          className="w-full rounded-md border border-border/60 bg-background px-3 py-2 text-sm mb-4"
        />

        <div className="flex flex-wrap gap-2">
          <OutcomeBtn
            tone="success"
            disabled={save.isPending}
            onClick={() => save.mutate("success")}
          >
            <CheckCircle2 className="h-4 w-4" /> Locked on
          </OutcomeBtn>
          <OutcomeBtn
            tone="partial"
            disabled={save.isPending}
            onClick={() => save.mutate("partial")}
          >
            <CircleAlert className="h-4 w-4" /> Unstable
          </OutcomeBtn>
          <OutcomeBtn tone="fail" disabled={save.isPending} onClick={() => save.mutate("fail")}>
            <XCircle className="h-4 w-4" /> No detection
          </OutcomeBtn>
        </div>
      </div>

      <h2 className="text-lg font-medium mb-3">Recorded runs</h2>
      <QueryState
        isLoading={tests.isLoading}
        error={tests.error}
        onRetry={() => tests.refetch()}
        label="test runs"
      />
      {!tests.isLoading && !tests.error && rows.length === 0 && (
        <p className="text-sm text-muted-foreground">
          No runs yet — complete a step above to start your baseline.
        </p>
      )}
      {rows.length > 0 && (
        <div className="overflow-x-auto rounded-2xl border border-border/60">
          <table className="w-full text-sm">
            <thead className="bg-card/40 text-left text-xs text-muted-foreground">
              <tr>
                <th className="px-3 py-2">When</th>
                <th className="px-3 py-2">Print</th>
                <th className="px-3 py-2">Step</th>
                <th className="px-3 py-2">Conditions</th>
                <th className="px-3 py-2">Detect</th>
                <th className="px-3 py-2">Outcome</th>
                <th className="px-3 py-2" />
              </tr>
            </thead>
            <tbody>
              {rows.map((r: any) => (
                <tr key={r.id} className="border-t border-border/40 align-top">
                  <td className="px-3 py-2 whitespace-nowrap text-muted-foreground">
                    {new Date(r.created_at).toLocaleString()}
                  </td>
                  <td className="px-3 py-2">{r.marker_label}</td>
                  <td className="px-3 py-2">{r.step_key}</td>
                  <td className="px-3 py-2 text-muted-foreground">
                    {r.lighting}
                    {r.distance_cm ? ` · ${r.distance_cm}cm` : ""}
                    {r.angle_deg != null ? ` · ${r.angle_deg}°` : ""}
                  </td>
                  <td className="px-3 py-2 tabular-nums">
                    {r.time_to_detect_ms != null
                      ? `${(r.time_to_detect_ms / 1000).toFixed(1)}s`
                      : "—"}
                  </td>
                  <td className="px-3 py-2">
                    <OutcomeBadge outcome={r.outcome} />
                    {r.notes && (
                      <div className="text-xs text-muted-foreground mt-1 max-w-xs">{r.notes}</div>
                    )}
                  </td>
                  <td className="px-3 py-2">
                    <button
                      onClick={() => delMut.mutate(r.id)}
                      aria-label="Delete run"
                      className="rounded-md p-1.5 text-muted-foreground hover:bg-accent hover:text-destructive"
                    >
                      <Trash2 className="h-4 w-4" />
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

function Stat({ label, value }: { label: string; value: string }) {
  return (
    <div className="rounded-2xl border border-border/60 bg-card/40 px-4 py-3">
      <div className="text-xs text-muted-foreground">{label}</div>
      <div className="text-2xl font-medium tabular-nums">{value}</div>
    </div>
  );
}

function OutcomeBadge({ outcome }: { outcome: Outcome }) {
  const map: Record<Outcome, string> = {
    success: "bg-emerald-500/15 text-emerald-500",
    partial: "bg-amber-500/15 text-amber-500",
    fail: "bg-destructive/15 text-destructive",
  };
  return <span className={`rounded-full px-2 py-0.5 text-xs ${map[outcome]}`}>{outcome}</span>;
}

function OutcomeBtn({
  tone,
  children,
  onClick,
  disabled,
}: {
  tone: Outcome;
  children: React.ReactNode;
  onClick: () => void;
  disabled?: boolean;
}) {
  const map: Record<Outcome, string> = {
    success: "border-emerald-500/40 text-emerald-500 hover:bg-emerald-500/10",
    partial: "border-amber-500/40 text-amber-500 hover:bg-amber-500/10",
    fail: "border-destructive/40 text-destructive hover:bg-destructive/10",
  };
  return (
    <button
      onClick={onClick}
      disabled={disabled}
      className={`inline-flex items-center gap-2 rounded-md border px-4 py-2 text-sm disabled:opacity-50 ${map[tone]}`}
    >
      {children}
    </button>
  );
}

import { createFileRoute, Link } from "@tanstack/react-router";
import { useServerFn } from "@tanstack/react-start";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { useState } from "react";
import { FolderPlus, Folder, Images, Boxes, Trash2, Pencil } from "lucide-react";
import { toast } from "sonner";
import { QueryState } from "@/components/QueryState";
import {
  assignToProject,
  createProject,
  deleteProject,
  listProjects,
  renameProject,
} from "@/lib/projects.functions";

export const Route = createFileRoute("/_authenticated/dashboard/projects")({
  component: ProjectsPage,
  head: () => ({
    meta: [
      { title: "Projects — Aether AR Dashboard" },
      {
        name: "description",
        content:
          "Group AR albums and experiences into client projects so every event stays organised and separate.",
      },
    ],
  }),
});

type Item = {
  id: string;
  title: string;
  slug: string | null;
  project_id: string | null;
  published: boolean;
};

function ProjectsPage() {
  const qc = useQueryClient();
  const list = useServerFn(listProjects);
  const create = useServerFn(createProject);
  const rename = useServerFn(renameProject);
  const remove = useServerFn(deleteProject);
  const assign = useServerFn(assignToProject);

  const [name, setName] = useState("");

  const query = useQuery({
    queryKey: ["projects"],
    queryFn: () => list(),
    staleTime: 30_000,
  });

  const invalidate = () => {
    qc.invalidateQueries({ queryKey: ["projects"] });
    qc.invalidateQueries({ queryKey: ["albums"] });
    qc.invalidateQueries({ queryKey: ["experiences"] });
  };

  const createMut = useMutation({
    mutationFn: (n: string) => create({ data: { name: n } }),
    onSuccess: () => {
      setName("");
      toast.success("Project created");
      invalidate();
    },
    onError: (e: any) => toast.error(e.message ?? "Could not create project"),
  });

  const renameMut = useMutation({
    mutationFn: (v: { id: string; name: string }) => rename({ data: v }),
    onSuccess: invalidate,
    onError: (e: any) => toast.error(e.message ?? "Rename failed"),
  });

  const deleteMut = useMutation({
    mutationFn: (id: string) => remove({ data: { id } }),
    onSuccess: () => {
      toast.success("Project removed — its content is now unfiled");
      invalidate();
    },
    onError: (e: any) => toast.error(e.message ?? "Delete failed"),
  });

  const assignMut = useMutation({
    mutationFn: (v: { kind: "album" | "experience"; id: string; project_id: string | null }) =>
      assign({ data: v }),
    onSuccess: invalidate,
    onError: (e: any) => toast.error(e.message ?? "Could not move item"),
  });

  const projects = query.data?.projects ?? [];
  const albums = (query.data?.albums ?? []) as Item[];
  const experiences = (query.data?.experiences ?? []) as Item[];

  const picker = (kind: "album" | "experience", item: Item) => (
    <select
      value={item.project_id ?? ""}
      onChange={(e) =>
        assignMut.mutate({
          kind,
          id: item.id,
          project_id: e.target.value || null,
        })
      }
      className="rounded-md border border-border/60 bg-background px-2 py-1 text-xs"
    >
      <option value="">Unfiled</option>
      {projects.map((p: any) => (
        <option key={p.id} value={p.id}>
          {p.name}
        </option>
      ))}
    </select>
  );

  const row = (kind: "album" | "experience", item: Item) => (
    <li
      key={item.id}
      className="flex items-center justify-between gap-3 rounded-lg border border-border/50 bg-card/30 px-3 py-2"
    >
      <div className="flex min-w-0 items-center gap-2">
        {kind === "album" ? (
          <Images className="h-4 w-4 shrink-0 text-muted-foreground" />
        ) : (
          <Boxes className="h-4 w-4 shrink-0 text-muted-foreground" />
        )}
        <span className="truncate text-sm">{item.title}</span>
        {!item.published && (
          <span className="rounded-full bg-muted px-2 py-0.5 text-[10px] text-muted-foreground">
            draft
          </span>
        )}
      </div>
      {picker(kind, item)}
    </li>
  );

  return (
    <div className="p-6 md:p-8 space-y-8">
      <header className="flex flex-wrap items-end justify-between gap-4">
        <div>
          <h1 className="text-2xl font-serif italic">Projects</h1>
          <p className="text-sm text-muted-foreground">
            Folders for your clients — keep each wedding, event or brand campaign separate. Content
            stays private to your account.
          </p>
        </div>
        <form
          onSubmit={(e) => {
            e.preventDefault();
            if (name.trim()) createMut.mutate(name.trim());
          }}
          className="flex items-center gap-2"
        >
          <input
            value={name}
            onChange={(e) => setName(e.target.value)}
            placeholder="e.g. Sharma Wedding"
            className="rounded-md border border-border/60 bg-background px-3 py-2 text-sm"
          />
          <button
            type="submit"
            disabled={createMut.isPending}
            className="inline-flex items-center gap-2 rounded-md bg-primary px-3 py-2 text-sm text-primary-foreground disabled:opacity-60"
          >
            <FolderPlus className="h-4 w-4" /> New project
          </button>
        </form>
      </header>

      <QueryState
        isLoading={query.isLoading}
        error={query.error}
        onRetry={() => void query.refetch()}
      />

      {query.data && (
        <div className="space-y-6">
          {projects.map((p: any) => {
            const pa = albums.filter((a) => a.project_id === p.id);
            const pe = experiences.filter((x) => x.project_id === p.id);
            return (
              <section key={p.id} className="rounded-xl border border-border/60 bg-card/20 p-4">
                <div className="mb-3 flex items-center justify-between gap-3">
                  <div className="flex items-center gap-2">
                    <Folder className="h-4 w-4 text-primary" />
                    <h2 className="text-base font-medium">{p.name}</h2>
                    <span className="text-xs text-muted-foreground">
                      {pa.length} album{pa.length === 1 ? "" : "s"} · {pe.length} experience
                      {pe.length === 1 ? "" : "s"}
                    </span>
                  </div>
                  <div className="flex items-center gap-1">
                    <button
                      onClick={() => {
                        const next = window.prompt("Rename project", p.name);
                        if (next?.trim()) renameMut.mutate({ id: p.id, name: next.trim() });
                      }}
                      className="rounded-md p-2 text-muted-foreground hover:bg-accent"
                      aria-label="Rename project"
                    >
                      <Pencil className="h-4 w-4" />
                    </button>
                    <button
                      onClick={() => {
                        if (
                          window.confirm(
                            "Remove this project? Albums and experiences inside it are kept and become unfiled.",
                          )
                        )
                          deleteMut.mutate(p.id);
                      }}
                      className="rounded-md p-2 text-muted-foreground hover:bg-destructive/10 hover:text-destructive"
                      aria-label="Delete project"
                    >
                      <Trash2 className="h-4 w-4" />
                    </button>
                  </div>
                </div>
                {pa.length + pe.length === 0 ? (
                  <p className="text-xs text-muted-foreground">
                    Nothing filed here yet — use the dropdowns below to move albums or experiences
                    into this project.
                  </p>
                ) : (
                  <ul className="space-y-2">
                    {pa.map((a) => row("album", a))}
                    {pe.map((x) => row("experience", x))}
                  </ul>
                )}
              </section>
            );
          })}

          <section className="rounded-xl border border-dashed border-border/60 p-4">
            <h2 className="mb-3 text-base font-medium">Unfiled</h2>
            {albums.filter((a) => !a.project_id).length +
              experiences.filter((x) => !x.project_id).length ===
            0 ? (
              <p className="text-xs text-muted-foreground">
                Everything is filed.{" "}
                <Link to="/dashboard/albums" className="underline">
                  Go to albums
                </Link>
              </p>
            ) : (
              <ul className="space-y-2">
                {albums.filter((a) => !a.project_id).map((a) => row("album", a))}
                {experiences.filter((x) => !x.project_id).map((x) => row("experience", x))}
              </ul>
            )}
          </section>
        </div>
      )}
    </div>
  );
}

import { createFileRoute, useNavigate, useSearch } from "@tanstack/react-router";
import { useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import { ShieldCheck, Loader2 } from "lucide-react";
import { z } from "zod";

const searchSchema = z.object({ redirect: z.string().optional() });

export const Route = createFileRoute("/_authenticated/mfa")({
  validateSearch: searchSchema,
  component: MFAPage,
});

function MFAPage() {
  const navigate = useNavigate();
  const { redirect } = useSearch({ from: "/_authenticated/mfa" });
  const [mode, setMode] = useState<"loading" | "enroll" | "challenge">("loading");
  const [factorId, setFactorId] = useState<string | null>(null);
  const [qr, setQr] = useState<string | null>(null);
  const [secret, setSecret] = useState<string | null>(null);
  const [code, setCode] = useState("");
  const [busy, setBusy] = useState(false);

  useEffect(() => {
    (async () => {
      const { data: factors } = await supabase.auth.mfa.listFactors();
      const verified = factors?.totp?.find((f) => f.status === "verified");
      if (verified) {
        setFactorId(verified.id);
        setMode("challenge");
        return;
      }
      // Enroll a new factor
      const { data, error } = await supabase.auth.mfa.enroll({ factorType: "totp" });
      if (error) {
        toast.error(error.message);
        return;
      }
      setFactorId(data.id);
      setQr(data.totp.qr_code);
      setSecret(data.totp.secret);
      setMode("enroll");
    })();
  }, []);

  async function verify() {
    if (!factorId) return;
    setBusy(true);
    try {
      const { data: challenge, error: chErr } = await supabase.auth.mfa.challenge({ factorId });
      if (chErr) throw chErr;
      const { error: vErr } = await supabase.auth.mfa.verify({
        factorId,
        challengeId: challenge.id,
        code: code.trim(),
      });
      if (vErr) throw vErr;
      toast.success("Two-factor verified");
      navigate({ to: redirect || "/dashboard" });
    } catch (e: any) {
      toast.error(e.message ?? "Verification failed");
    } finally {
      setBusy(false);
    }
  }

  if (mode === "loading") {
    return (
      <div className="min-h-screen grid place-items-center bg-background text-foreground">
        <Loader2 className="animate-spin h-6 w-6 text-muted-foreground" />
      </div>
    );
  }

  return (
    <div className="min-h-screen grid place-items-center bg-background text-foreground p-6">
      <div className="max-w-md w-full rounded-2xl border border-border/60 bg-card/40 p-8">
        <div className="flex items-center gap-3 mb-6">
          <ShieldCheck className="h-6 w-6 text-primary" />
          <h1 className="text-2xl font-serif italic">
            {mode === "enroll" ? "Enable two-factor" : "Enter your code"}
          </h1>
        </div>

        {mode === "enroll" && (
          <>
            <p className="text-sm text-muted-foreground mb-4">
              Admin accounts require TOTP. Scan this QR code with Google Authenticator, 1Password,
              or Authy — then enter the 6-digit code below.
            </p>
            {qr && (
              <img
                src={qr}
                alt="TOTP QR"
                className="w-48 h-48 mx-auto mb-3 rounded-md bg-white p-2"
              />
            )}
            {secret && (
              <p className="text-xs text-center text-muted-foreground mb-4">
                Or enter secret manually:{" "}
                <code className="font-mono text-foreground">{secret}</code>
              </p>
            )}
          </>
        )}

        {mode === "challenge" && (
          <p className="text-sm text-muted-foreground mb-4">
            Open your authenticator app and enter the current 6-digit code.
          </p>
        )}

        <input
          value={code}
          onChange={(e) => setCode(e.target.value.replace(/\D/g, "").slice(0, 6))}
          inputMode="numeric"
          placeholder="000000"
          className="w-full text-center text-2xl font-mono tracking-widest rounded-md border border-border bg-background px-3 py-3 mb-4"
        />

        <button
          onClick={verify}
          disabled={busy || code.length !== 6}
          className="w-full rounded-md bg-primary text-primary-foreground px-4 py-2 text-sm font-medium hover:bg-primary/90 disabled:opacity-50"
        >
          {busy ? "Verifying…" : mode === "enroll" ? "Enable 2FA" : "Verify"}
        </button>
      </div>
    </div>
  );
}

import { createFileRoute, Link, useNavigate } from "@tanstack/react-router";
import { useServerFn } from "@tanstack/react-start";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { getMyAccount } from "@/lib/account.functions";
import { Clock, Copy, LogOut, ShieldX, Sparkles } from "lucide-react";
import { toast } from "sonner";

export const Route = createFileRoute("/_authenticated/pending")({
  component: PendingPage,
});

function PendingPage() {
  const navigate = useNavigate();
  const qc = useQueryClient();
  const fetchAccount = useServerFn(getMyAccount);

  const { data, isLoading } = useQuery({
    queryKey: ["my-account"],
    queryFn: () => fetchAccount(),
    refetchInterval: 30_000,
  });

  const status = data?.profile?.approval_status ?? "pending";
  const license = data?.license ?? null;

  async function signOut() {
    await qc.cancelQueries();
    qc.clear();
    await supabase.auth.signOut();
    navigate({ to: "/auth", replace: true });
  }

  return (
    <div className="min-h-screen grid place-items-center px-6 py-16 bg-background text-foreground">
      <div className="w-full max-w-lg rounded-2xl border border-border/60 bg-card/30 backdrop-blur-xl p-8">
        <Link to="/" className="flex items-center gap-2 mb-8">
          <Sparkles className="h-5 w-5 text-primary" />
          <span className="text-lg font-serif italic">Aether AR</span>
        </Link>

        {status === "rejected" ? (
          <>
            <ShieldX className="h-8 w-8 text-destructive mb-4" />
            <h1 className="text-2xl font-serif mb-2">Account not approved</h1>
            <p className="text-sm text-muted-foreground">
              {data?.profile?.rejection_reason ||
                "An administrator declined access for this account. Reply to your onboarding email if you think this is a mistake."}
            </p>
          </>
        ) : status === "approved" ? (
          <>
            <h1 className="text-2xl font-serif mb-2">You're approved</h1>
            <p className="text-sm text-muted-foreground mb-6">
              Your workspace and licence are ready.
            </p>
            {license && <LicenseCard license={license} />}
            <Link
              to="/dashboard"
              className="mt-6 inline-flex rounded-full bg-primary text-primary-foreground px-5 py-2 text-sm font-medium"
            >
              Open dashboard
            </Link>
          </>
        ) : (
          <>
            <Clock className="h-8 w-8 text-primary mb-4" />
            <h1 className="text-2xl font-serif mb-2">Waiting for admin approval</h1>
            <p className="text-sm text-muted-foreground">
              Your account <span className="text-foreground">{data?.profile?.email}</span> was
              created successfully. An administrator has to approve it before you can publish AR
              experiences. Your licence key is issued automatically the moment you're approved —
              this page refreshes itself.
            </p>
            {isLoading && (
              <p className="mt-4 text-xs text-muted-foreground animate-pulse">
                Checking your status…
              </p>
            )}
          </>
        )}

        <button
          onClick={signOut}
          className="mt-8 flex items-center gap-2 text-sm text-muted-foreground hover:text-foreground transition-colors"
        >
          <LogOut className="h-4 w-4" /> Sign out
        </button>
      </div>
    </div>
  );
}

function LicenseCard({ license }: { license: any }) {
  return (
    <div className="rounded-xl border border-border/60 bg-background/40 p-4">
      <p className="text-xs uppercase tracking-wider text-muted-foreground mb-2">
        Your licence key
      </p>
      <div className="flex items-center gap-2">
        <code className="text-sm break-all">{license.license_key}</code>
        <button
          onClick={() => {
            navigator.clipboard.writeText(license.license_key);
            toast.success("Licence key copied");
          }}
          className="shrink-0 rounded-md p-1.5 hover:bg-accent"
          aria-label="Copy licence key"
        >
          <Copy className="h-4 w-4" />
        </button>
      </div>
      <p className="mt-2 text-xs text-muted-foreground">
        {license.plan} · {license.max_activations} activation
        {license.max_activations === 1 ? "" : "s"} · {license.status}
      </p>
    </div>
  );
}

